(window.CLAVE_TODO=window.CLAVE_TODO||{})[16]=[{"a":"Artículo 21 — Colaboración entre las Administraciones públicas","q":[{"i":"16-1","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. La Administración General del Estado y las Administraciones de las Comunidades Autónomas cooperan para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus respectivas competencias y, en especial, en sus actuaciones de planificación. En el seno ______________ podrán adoptarse planes y programas conjuntos de actuación con esta finalidad.","o":["del Instituto de la Mujer.","del Observatorio Estatal de Violencia sobre la Mujer.","de la Delegación del Gobierno contra la Violencia de Género.","de la Conferencia Sectorial de la Mujer."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de la Conferencia Sectorial de la Mujer</mark></span>El <span class=\"ref-norma\">art. 21.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"La Administración General del Estado y las Administraciones de las Comunidades Autónomas cooperarán para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus respectivas competencias y, en especial, en sus actuaciones de planificación. En el seno de la Conferencia Sectorial de la Mujer podrán adoptarse planes y programas conjuntos de actuación con esta finalidad.\"</span>"},{"i":"16-116","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Colaboración entre las Administraciones Públicas. Integrarán el derecho de igualdad en el ejercicio de sus competencias y colaborarán, a tal efecto, con el resto de las Administraciones Públicas:","o":["La Administración General del Estado.","Las Administraciones de las Comunidades Autónomas.","Las Entidades Locales.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Entidades Locales</mark></span>El <span class=\"ref-norma\">art. 21.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Las Entidades Locales integrarán el derecho de igualdad en el ejercicio de sus competencias y colaborarán, a tal efecto, con el resto de las Administraciones públicas.\"</span>. La AGE y las Comunidades Autónomas «cooperarán» (art. 21.1); son las Entidades Locales las que «integrarán el derecho de igualdad en el ejercicio de sus competencias y colaborarán»."},{"i":"16-120","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Quiénes cooperarán para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus respectivas competencias y, en especial, en sus actuaciones de planificación?","o":["Las Administraciones de las Comunidades Autónomas y las Entidades Locales.","La Administración General del Estado, las Administraciones de las Comunidades Autónomas y las Entidades Locales.","La Administración General del Estado y las Administraciones de las Comunidades Autónomas.","La Administración General del Estado y las Entidades Locales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Administración General del Estado y las Administraciones de las Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 21.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"La Administración General del Estado y las Administraciones de las Comunidades Autónomas cooperarán para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus respectivas competencias y, en especial, en sus actuaciones de planificación. En el seno de la Conferencia Sectorial de la Mujer podrán adoptarse planes y programas conjuntos de actuación con esta finalidad.\"</span>. Las Entidades Locales no «cooperan»: integran el derecho de igualdad y colaboran con el resto de Administraciones (art. 21.2)."},{"i":"16-ia-1048","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Colaboración entre las Administraciones públicas. En el seno de la Conferencia Sectorial de la Mujer podrán adoptarse:","o":["planes y programas de actuación vinculantes para las Comunidades Autónomas.","planes y programas conjuntos de actuación con esta finalidad.","protocolos y convenios de colaboración con las entidades locales.","acuerdos y recomendaciones dirigidos a las empresas privadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">planes y programas conjuntos de actuación con esta finalidad</mark></span>El <span class=\"ref-norma\">art. 21.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"En el seno de la Conferencia Sectorial de la Mujer podrán adoptarse planes y programas conjuntos de actuación con esta finalidad\"</span>. La Conferencia Sectorial de la Mujer puede adoptar planes y programas conjuntos de actuación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 3/2007 (R1 a R14) R1 R2 R3 R4 R5 R6 R7 R8 R9 R10 R11 R12 R13 R14","q":[{"i":"16-2","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El Plan de Igualdad en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella será aprobado por:","o":["Las Cortes Generales.","El Gobierno.","El Presidente del Gobierno.","El Ministro de Asuntos Sociales e Igualdad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Gobierno</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella.\"</span>. Ojo: el Plan lo APRUEBA «el Gobierno» (art. 64) y su cumplimiento lo EVALÚA «el Consejo de Ministros»."},{"i":"16-10","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Consecuencias jurídicas de las conductas discriminatorias. Esta Ley establece que los actos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar, en su caso, a un sistema ______________ que prevenga la realización de conductas discriminatorias.","o":["Ejemplar y defensivo de castigos y recompensas.","Eficaz y disuasorio de sanciones.","De penalizaciones y recompensas.","De protección y reparación integral."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Eficaz y disuasorio de sanciones</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-12","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad de trato entre mujeres y hombres supone:","o":["La ausencia de toda discriminación, directa o indirecta, por razón de sexo.","La ausencia de toda discriminación derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.","La ausencia de toda discriminación, directa o indirecta, por acoso sexual.","a) y b) son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a) y b) son correctas</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.\"</span>. Las opciones A y B reproducen cada una parte del artículo, por eso «a) y b) son correctas»."},{"i":"16-13","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. El principio de igualdad y la tutela contra la discriminación. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema ______________ de sanciones que prevenga la realización de conductas discriminatorias.","o":["Eficaz y disuasorio.","Disuasorio y proporcional.","Disuasorio y eficiente.","Ninguna de las anteriores es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Eficaz y disuasorio</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-18","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. El principio de igualdad en el empleo público. ¿Con qué frecuencia los departamentos ministeriales remitirán información relativa a la aplicación efectiva en cada uno de ellos del principio de igualdad entre mujeres y hombres al Ministerio de Trabajo?:","o":["Al menos anualmente.","Al menos semestralmente.","Al menos cada diez meses.","Ninguna opción es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al menos anualmente</mark></span>El <span class=\"ref-norma\">art. 63 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Todos los Departamentos Ministeriales y Organismos Públicos remitirán, al menos anualmente, a los Ministerios de Trabajo y Asuntos Sociales y de Administraciones Públicas, información relativa a la aplicación efectiva en cada uno de ellos del principio de igualdad entre mujeres y hombres, con especificación, mediante la desagregación por sexo de los datos, de la distribución de su plantilla, grupo de titulación, nivel de complemento de destino y retribuciones promediadas de su personal.\"</span>"},{"i":"16-25","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo:","o":["Se considerarán nulos y sin efecto.","Darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionales al perjuicio sufrido.","En su caso, darán lugar a responsabilidad a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","Todos los opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos los opciones anteriores son correctas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>. Las tres afirmaciones (nulidad, reparaciones o indemnizaciones y sistema de sanciones) son literales del artículo, así que «todas son correctas»."},{"i":"16-41","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. ¿Qué supone el principio de igualdad de trato entre hombres y mujeres?","o":["Supone la ausencia de toda discriminación directa por razón de sexo, y, especialmente, las derivadas de la maternidad, la paternidad, o asunción de obligaciones familiares y el estado civil.","Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de las esferas política, civil, laboral, económica, social y cultural.","Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.","Supone la ausencia de toda discriminación directa por razón de sexo, y, especialmente, las derivadas de las esferas política, civil, laboral, económica, social y cultural."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.\"</span>"},{"i":"16-42","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente, en el sistema de:","o":["Ascensos, accesos, destinos, formación y retribuciones.","Formación, destinos, situaciones administrativas, ascensos y retribuciones.","Acceso, formación, ascensos, destinos y situaciones administrativas.","Retribuciones, destinos, situaciones administrativas, ascensos y acceso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Acceso, formación, ascensos, destinos y situaciones administrativas</mark></span>El <span class=\"ref-norma\">art. 67 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente, en el sistema de acceso, formación, ascensos, destinos y situaciones administrativas.\"</span>"},{"i":"16-43","p":"LO 3/2007 - Tutela Judicial Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a ______ probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad.","o":["Las personas jurídicas con interés legítimo.","La persona demandada.","Las personas físicas con interés legítimo.","La persona acosada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La persona demandada</mark></span>El <span class=\"ref-norma\">art. 13.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad.\"</span>"},{"i":"16-47","p":"LO 3/2007 - Aprobación del Plan de Igualdad en A.G.E. Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. ¿Quién aprobará un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella?","o":["El Gobierno, al inicio de cada legislatura.","El Ministerio de Igualdad.","El Consejo de Ministros.","El Ministerio del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Gobierno, al inicio de cada legislatura</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella.\"</span>. Ojo: el Plan lo APRUEBA «el Gobierno» (art. 64) y su cumplimiento lo EVALÚA «el Consejo de Ministros»."},{"i":"16-50","p":"LO 3/2007 - Finalidad de la Ley Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Esta Ley tiene por objeto hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres, en particular mediante la eliminación de la discriminación de la mujer, sea cual fuere su circunstancia o condición, en cualesquiera de los ámbitos de la vida y, singularmente, en las esferas política, civil, laboral, económica, social y cultural para, en el desarrollo de los artículos 9.2 y 14 de la Constitución, alcanzar una sociedad... Señale la incorrecta.","o":["Más justa.","Más solidaria.","Más democrática.","Más proporcionada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Más proporcionada</mark></span>El <span class=\"ref-norma\">art. 1.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"alcanzar una sociedad más democrática, más justa y más solidaria.\"</span>"},{"i":"16-53","p":"LO 3/2007 - Imputación de la Prueba Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, ¿a quién le corresponderá probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad?","o":["A las fuerzas y cuerpos de seguridad.","Al órgano judicial.","A la parte actora.","A la persona demandada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A la persona demandada</mark></span>El <span class=\"ref-norma\">art. 13.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad.\"</span>"},{"i":"16-67","p":"(LO 3/2007 - LOIG) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo:","o":["Se considerarán nulos y sin efecto.","Darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionales al perjuicio sufrido.","En su caso, darán lugar a responsabilidad a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","Todos los opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos los opciones anteriores son correctas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>. Las tres afirmaciones (nulidad, reparaciones o indemnizaciones y sistema de sanciones) son literales del artículo, así que «todas son correctas»."},{"i":"16-88","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad y la tutela contra la discriminación. ¿Cómo se denomina cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo?","o":["Acoso sexual.","Acoso por razón de sexo.","Discriminación directa por razón de sexo.","Discriminación indirecta por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Acoso por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-89","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente, en el sistema de: señale la INCORRECTA.","o":["Ascensos.","Retribuciones.","Formación.","Situaciones administrativas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Retribuciones</mark></span>El <span class=\"ref-norma\">art. 67 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente, en el sistema de acceso, formación, ascensos, destinos y situaciones administrativas.\"</span>"},{"i":"16-100","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Consecuencias jurídicas de las conductas discriminatorias. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean: señale la INCORRECTA.","o":["Reales.","Efectivas.","Proporcionadas al perjuicio sufrido.","Simbólicas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Simbólicas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-108","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán ______________, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","o":["anulables y con efectos limitados","nulos y sin efecto","ineficaces y rescindibles","inexistentes y sin responsabilidad"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">nulos y sin efecto</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-109","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de: señale la INCORRECTA.","o":["La condición laboral.","La maternidad.","La asunción de obligaciones familiares.","El estado civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La condición laboral</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.\"</span>"},{"i":"16-110","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Cómo se denomina cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo?","o":["Discriminación directa por razón de sexo.","Acoso sexual.","Discriminación indirecta por razón de sexo.","Acoso por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Acoso por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-113","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad y la tutela contra la discriminación. Señale la INCORRECTA:","o":["La igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas.","El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la ausencia de obligaciones familiares y el estado civil.","El principio de igualdad de trato y de oportunidades entre mujeres y hombres, aplicable en el ámbito del empleo privado y en el del empleo público, se garantizará, en los términos previstos en la normativa aplicable, en el acceso al empleo, incluso al trabajo por cuenta propia, en la formación profesional, en la promoción profesional, en las condiciones de trabajo, incluidas las retributivas y las de despido, y en la afiliación y participación en las organizaciones sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas.","No constituirá discriminación en el acceso al empleo, incluida la formación necesaria, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional esencial y determinante, siempre y cuando el objetivo sea legítimo y el requisito proporcionado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la ausencia de obligaciones familiares y el estado civil</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.\"</span>. La opción B sustituye «la asunción de obligaciones familiares» por «la ausencia de obligaciones familiares»."},{"i":"16-114","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. La aprobación de convocatorias de pruebas selectivas para el acceso al empleo público deberá acompañarse:","o":["De un informe de la prohibición de discriminación por razón de sexo, incluidos los casos de urgencia y siempre sin perjuicio del impacto de género.","De un informe de impacto de género, incluidos los casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo.","De un informe de la prohibición de discriminación por razón de sexo, salvo en casos de urgencia y siempre sin perjuicio del impacto de género.","De un informe de impacto de género, salvo en casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De un informe de impacto de género, salvo en casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 55 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"La aprobación de convocatorias de pruebas selectivas para el acceso al empleo público deberá acompañarse de un informe de impacto de género, salvo en casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo.\"</span>"},{"i":"16-118","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Quién elaborará un informe periódico sobre el conjunto de sus actuaciones en relación con la efectividad del principio de igualdad entre mujeres y hombres?","o":["El Ministerio de Justicia.","El Gobierno.","Las Cortes Generales.","El Ministerio de Igualdad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Gobierno</mark></span>El <span class=\"ref-norma\">art. 18 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"En los términos que reglamentariamente se determinen, el Gobierno elaborará un informe periódico sobre el conjunto de sus actuaciones en relación con la efectividad del principio de igualdad entre mujeres y hombres. De este informe se dará cuenta a las Cortes Generales.\"</span>"},{"i":"16-119","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Consecuencias jurídicas de las conductas discriminatorias. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones e indemnizaciones que sean ______ al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","o":["Proporcionales, eficaces y realistas.","Reales, efectivas y proporcionadas.","Razonables y proporcionadas.","Efectivas, reales y exigibles."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Reales, efectivas y proporcionadas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-121","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Con qué periodicidad todos los Departamentos Ministeriales y Organismos Públicos remitirán a los Ministerios de Trabajo y Asuntos Sociales y de Administraciones Públicas, información relativa a la aplicación efectiva en cada uno de ellos del principio de igualdad entre mujeres y hombres?","o":["Al menos trimestralmente.","Al menos mensualmente.","Al menos anualmente.","Al menos semestralmente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al menos anualmente</mark></span>El <span class=\"ref-norma\">art. 63 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Todos los Departamentos Ministeriales y Organismos Públicos remitirán, al menos anualmente, a los Ministerios de Trabajo y Asuntos Sociales y de Administraciones Públicas, información relativa a la aplicación efectiva en cada uno de ellos del principio de igualdad entre mujeres y hombres, con especificación, mediante la desagregación por sexo de los datos, de la distribución de su plantilla, grupo de titulación, nivel de complemento de destino y retribuciones promediadas de su personal.\"</span>"},{"i":"16-128","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Cómo se denomina la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable?","o":["Acoso por razón de sexo.","Discriminación directa por razón de sexo.","Acoso sexual.","Discriminación indirecta por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Discriminación directa por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 6.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"1. Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.\"</span>"},{"i":"16-129","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean ______ al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","o":["Reales.","Efectivas.","Proporcionadas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>. Los tres adjetivos del artículo son «reales, efectivas y proporcionadas»: todas las opciones son correctas."},{"i":"16-130","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. La igualdad de trato y de oportunidades entre mujeres y hombres es un ______ del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas.","o":["Principio informador.","Principio superior.","Principio responsable.","Principio jerárquico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Principio informador</mark></span>El <span class=\"ref-norma\">art. 4 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"La igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas.\"</span>"},{"i":"16-132","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados, se considera:","o":["Discriminación directa por razón de sexo.","Discriminación indirecta por razón de sexo.","Acoso sexual.","Acoso por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Discriminación indirecta por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 6.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.\"</span>"},{"i":"16-138","p":"Ley Orgánica 3/2007. El Plan de Igualdad en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella será aprobado por:","o":["Las Cortes Generales.","El Gobierno.","El Presidente del Gobierno.","El Ministro de Asuntos Sociales e Igualdad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Gobierno</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella.\"</span>. Ojo: el Plan lo APRUEBA «el Gobierno» (art. 64) y su cumplimiento lo EVALÚA «el Consejo de Ministros»."},{"i":"16-141","p":"Ley Orgánica 3/2007. La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados, se considera:","o":["Discriminación directa por razón de sexo.","Discriminación indirecta por razón de sexo.","Acoso sexual.","Acoso por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Discriminación indirecta por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 6.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.\"</span>"},{"i":"16-147","p":"Ley Orgánica 3/2007. Consecuencias jurídicas de las conductas discriminatorias. Esta Ley establece que los actos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar, en su caso, a un sistema ______ que prevenga la realización de conductas discriminatorias.","o":["Ejemplar y defensivo de castigos y recompensas.","Eficaz y disuasorio de sanciones.","Proporcionado y justo de indemnizaciones.","Reparador y educativo de consecuencias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Eficaz y disuasorio de sanciones</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>"},{"i":"16-149","p":"Ley Orgánica 3/2007. El principio de igualdad de trato entre mujeres y hombres supone:","o":["La ausencia de toda discriminación, directa o indirecta, por razón de sexo.","La ausencia de toda discriminación derivada de la maternidad, la asunción de obligaciones familiares y el estado civil.","La ausencia de toda discriminación, directa o indirecta, por acoso sexual.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 3 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil.\"</span>"},{"i":"16-152","p":"Ley Orgánica 3/2007. Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:","o":["Discriminación directa por razón de sexo.","Discriminación indirecta por razón de sexo.","Acoso sexual.","Acoso por razón de sexo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Discriminación directa por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 8 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad.\"</span>"},{"i":"16-157","p":"Ley Orgánica 3/2007. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean ______ al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","o":["Reales.","Efectivas.","Proporcionadas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean reales, efectivas y proporcionadas al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.\"</span>. Los tres adjetivos del artículo son «reales, efectivas y proporcionadas»: todas las opciones son correctas."},{"i":"16-161","p":"Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres. De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, ¿a quién le corresponderá probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad?:","o":["A la persona demandada.","Al órgano judicial.","A la parte actora.","A las Fuerzas y Cuerpos de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la persona demandada.</mark></span><span class=\"ref-norma\">Art. 13 · Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres</span>. El artículo 13 de la LO 3/2007 establece la inversión de la carga de la prueba (burden of proof). Una vez que la persona demandante aporta indicios de discriminación, corresponde a la parte demandada (quien adopta la medida) probar la justificación objetiva y razonable de la medida y su proporcionalidad."},{"i":"16-169","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. ¿Quién aprueba el Plan de Igualdad en la Administración General del Estado y en los Organismos Públicos vinculados o dependientes de ella?:","o":["El Gobierno.","El Ministerio de Igualdad.","El Ministerio de Justicia.","El Ministerio del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Gobierno.</mark></span><span class=\"ref-norma\">Art. 64.1 · Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres</span>. El artículo 64.1 de la LO 3/2007 establece que el Plan de Igualdad de la Administración General del Estado y de los Organismos Públicos vinculados o dependientes de ella será aprobado por el Gobierno."},{"i":"16-171","p":"Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres. La situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable se considera:","o":["Discriminación indirecta por razón de sexo.","Acoso por razón de sexo.","Discriminación directa por razón de sexo.","Acoso sexual."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Discriminación directa por razón de sexo.</mark></span><span class=\"ref-norma\">Art. 6 · Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres</span>. Esta definición corresponde textualmente a la Discriminación directa por razón de sexo, según el artículo 6 de la LO 3/2007."},{"i":"16-178","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Ámbito de aplicación. Las obligaciones establecidas en esta Ley serán de aplicación a toda persona, física o jurídica, que se encuentre o actúe en territorio español, cualquiera que fuese su:","o":["Nacionalidad, domicilio o residencia.","Nacionalidad, residencia o vecindad.","Domicilio, residencia o condición personal.","Nacionalidad, domicilio o estado civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Nacionalidad, domicilio o residencia</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"cualquiera que fuese su nacionalidad, domicilio o residencia\"</span>"},{"i":"16-ia-1003","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Objeto de la Ley. A estos efectos, la Ley establece principios de actuación de los Poderes Públicos, regula derechos y deberes de las personas físicas y jurídicas, tanto públicas como privadas, y prevé medidas destinadas a eliminar y corregir en los sectores público y privado, toda forma de:","o":["discriminación por razón de género.","desigualdad por razón de sexo.","discriminación por razón de sexo.","violencia por razón de sexo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"toda forma de discriminación por razón de sexo\"</span>. La Ley prevé medidas para eliminar y corregir toda forma de discriminación por razón de sexo, no de género, desigualdad o violencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1004","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Ámbito de aplicación. Señale la INCORRECTA sobre el ámbito de aplicación de la Ley:","o":["Todas las personas gozarán de los derechos derivados del principio de igualdad de trato y de la prohibición de discriminación por razón de sexo, en los términos que se determinen reglamentariamente.","Las obligaciones establecidas en la Ley serán de aplicación únicamente a las personas, físicas o jurídicas, de nacionalidad española que actúen en territorio español.","Las obligaciones establecidas en la Ley serán de aplicación a toda persona, física o jurídica, que se encuentre o actúe en territorio español.","La nacionalidad, el domicilio o la residencia de la persona no excluyen la aplicación de las obligaciones establecidas en la Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las obligaciones establecidas en la Ley serán de aplicación únicamente a las personas, físicas o jurídicas, de nacionalidad española que actúen en territorio español</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Las obligaciones establecidas en esta Ley serán de aplicación a toda persona, física o jurídica, que se encuentre o actúe en territorio español, cualquiera que fuese su nacionalidad, domicilio o residencia\"</span>. La Ley se aplica a toda persona que se encuentre o actúe en territorio español, cualquiera que fuese su nacionalidad, domicilio o residencia; no solo a los españoles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1005","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Ámbito de aplicación. Las obligaciones establecidas en esta Ley serán de aplicación a toda persona, física o jurídica, que se encuentre o actúe en territorio español, cualquiera que fuese su __________.","o":["nacionalidad, domicilio o residencia","nacionalidad, domicilio o vecindad","nacionalidad, residencia o condición, salvo que la autoridad judicial disponga otra cosa.","domicilio, residencia o estado civil"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">nacionalidad, domicilio o residencia</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"cualquiera que fuese su nacionalidad, domicilio o residencia\"</span>. El texto dice nacionalidad, domicilio o residencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1006","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad de trato entre mujeres y hombres. El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de:","o":["la maternidad, la asunción de obligaciones familiares y la orientación sexual.","el embarazo, la asunción de obligaciones laborales y el estado civil.","la maternidad, la conciliación de la vida laboral y el estado civil.","la maternidad, la asunción de obligaciones familiares y el estado civil."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la maternidad, la asunción de obligaciones familiares y el estado civil</mark></span>El <span class=\"ref-norma\">art. 3 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil\"</span>. Se citan expresamente la maternidad, la asunción de obligaciones familiares y el estado civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1013","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Discriminación directa e indirecta. Señale la INCORRECTA en relación con la discriminación por razón de sexo:","o":["Se considera discriminatoria la orden de discriminar por razón de sexo solo cuando llegue a ejecutarse materialmente.","Se considera discriminación directa la situación en que una persona sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.","Se considera discriminación indirecta la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro.","La discriminación indirecta no existe si la disposición, criterio o práctica puede justificarse objetivamente en atención a una finalidad legítima con medios necesarios y adecuados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Se considera discriminatoria la orden de discriminar por razón de sexo solo cuando llegue a ejecutarse materialmente</mark></span>El <span class=\"ref-norma\">art. 6 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"En cualquier caso, se considera discriminatoria toda orden de discriminar, directa o indirectamente, por razón de sexo\"</span>. Toda orden de discriminar, directa o indirectamente, se considera discriminatoria en cualquier caso, se ejecute o no. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1017","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acoso sexual y acoso por razón de sexo. Se considerarán en todo caso discriminatorios:","o":["el acoso sexual y el acoso por razón de sexo.","el acoso sexual y el acoso laboral.","el acoso por razón de sexo y el acoso moral.","el acoso sexual reiterado y el acoso por razón de sexo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el acoso sexual y el acoso por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 7.3 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Se considerarán en todo caso discriminatorios el acoso sexual y el acoso por razón de sexo\"</span>. Ambos acosos son discriminatorios en todo caso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1018","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acoso sexual y acoso por razón de sexo. El condicionamiento de un derecho o de una expectativa de derecho a la aceptación de una situación constitutiva de acoso sexual o de acoso por razón de sexo se considerará también:","o":["acto constitutivo de delito de acoso sexual.","falta muy grave de carácter disciplinario.","una forma de acoso laboral.","acto de discriminación por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">acto de discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 7.4 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"se considerará también acto de discriminación por razón de sexo\"</span>. El condicionamiento de un derecho o de una expectativa de derecho es también acto de discriminación por razón de sexo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1019","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Discriminación por embarazo o maternidad. Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con:","o":["el embarazo, el parto o la lactancia.","la maternidad o las obligaciones familiares.","el embarazo o la maternidad.","el embarazo o la asunción de cargas familiares."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el embarazo o la maternidad</mark></span>El <span class=\"ref-norma\">art. 8 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad\"</span>. Se refiere al embarazo o la maternidad, y la califica como discriminación directa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1021","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Consecuencias jurídicas de las conductas discriminatorias. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán:","o":["nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones.","anulables, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones, salvo que la autoridad judicial disponga otra cosa.","nulos de pleno derecho, aunque no darán lugar a responsabilidad por sí solos.","nulos y sin efecto, aunque solo darán lugar a responsabilidad administrativa sancionadora."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones</mark></span>El <span class=\"ref-norma\">art. 10 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"se considerarán nulos y sin efecto, y darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones\"</span>. Son nulos y sin efecto y dan lugar a responsabilidad mediante reparaciones o indemnizaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1022","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Consecuencias jurídicas de las conductas discriminatorias. Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo darán lugar a responsabilidad a través de un sistema de reparaciones o indemnizaciones que sean __________ al perjuicio sufrido, así como, en su caso, a través de un sistema eficaz y disuasorio de sanciones que prevenga la realización de conductas discriminatorias.","o":["reales, efectivas y suficientes","efectivas, proporcionadas y disuasorias","justas, efectivas y proporcionadas","reales, efectivas y proporcionadas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">reales, efectivas y proporcionadas</mark></span>El <span class=\"ref-norma\">art. 10 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"que sean reales, efectivas y proporcionadas al perjuicio sufrido\"</span>. Las reparaciones o indemnizaciones han de ser reales, efectivas y proporcionadas al perjuicio sufrido; el sistema de sanciones es eficaz y disuasorio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1029","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Prueba. De acuerdo con las Leyes procesales, en aquellos procedimientos en los que las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias, por razón de sexo, corresponderá a la persona __________ probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad.","o":["demandada","actora","denunciada","afectada"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">demandada</mark></span>El <span class=\"ref-norma\">art. 13.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad\"</span>. Se invierte la carga de la prueba: corresponde a la persona demandada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1038","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos la implantación de un lenguaje no sexista en el ámbito __________ y su fomento en la totalidad de las relaciones sociales, culturales y artísticas.","o":["educativo","institucional, sin perjuicio de lo previsto en la normativa vigente.","jurídico","administrativo"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">administrativo</mark></span>El <span class=\"ref-norma\">art. 14.11 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"La implantación de un lenguaje no sexista en el ámbito administrativo y su fomento en la totalidad de las relaciones sociales, culturales y artísticas\"</span>. El lenguaje no sexista se implanta en el ámbito administrativo y se fomenta en las relaciones sociales, culturales y artísticas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1110","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Informe de impacto de género en las pruebas de acceso al empleo público. La aprobación de convocatorias de pruebas selectivas para el acceso al empleo público deberá acompañarse de un informe de impacto de género, salvo en casos de:","o":["urgencia y siempre que no se establezcan reservas de plazas por razón de sexo.","extrema necesidad y siempre sin perjuicio de la prohibición de discriminación por razón de sexo.","urgencia, con independencia de la prohibición de discriminación por razón de sexo.","urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 55 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"salvo en casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo\"</span>. Solo se exceptúan los casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1124","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Evaluación sobre la igualdad en el empleo público. Todos los Departamentos Ministeriales y Organismos Públicos remitirán, __________, a los Ministerios de Trabajo y Asuntos Sociales y de Administraciones Públicas, información relativa a la aplicación efectiva en cada uno de ellos del principio de igualdad entre mujeres y hombres.","o":["semestralmente","al menos anualmente","al menos trimestralmente","cuando sean requeridos para ello"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al menos anualmente</mark></span>El <span class=\"ref-norma\">art. 63 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"remitirán, al menos anualmente, a los Ministerios de Trabajo y Asuntos Sociales y de Administraciones Públicas\"</span>. La remisión es, al menos, anual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1127","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Plan de Igualdad en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado será objeto de negociación, y en su caso acuerdo, con la representación legal de los empleados públicos en la forma que se determine en la legislación sobre negociación colectiva en la Administración Pública y su cumplimiento será evaluado __________ por el Consejo de Ministros.","o":["bienalmente","semestralmente","anualmente","al final de cada legislatura"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">anualmente</mark></span>El <span class=\"ref-norma\">art. 64 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"su cumplimiento será evaluado anualmente por el Consejo de Ministros\"</span>. El Consejo de Ministros evalúa anualmente su cumplimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1143","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. Cualquier empleada o empleado público tiene la __________ de poner en conocimiento los casos de posible acoso sexual o acoso por razón de sexo que conozca.","o":["facultad","posibilidad","obligación","recomendación"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">obligación</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Cualquier empleada o empleado público tiene la obligación de poner en conocimiento los casos de posible acoso sexual o acoso por razón de sexo que conozca\"</span>. Es una obligación, no una facultad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1247","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. Entre las medidas de prevención figura la elaboración de estadísticas con datos numéricos, desagregados por __________, sobre el número de intervenciones y casos de acoso sexual y acoso por razón de sexo, así como publicación periódica de estos datos, manteniendo siempre el anonimato de las personas implicadas.","o":["edad","departamento","sexo","categoría profesional"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sexo</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Elaboración de estadísticas con datos numéricos, desagregados por sexo\"</span>. Los datos numéricos se desagregan por sexo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1331","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · V. Evaluación y seguimiento del informe de conclusiones. En el ámbito de cada Mesa Delegada, a través de sus comisiones de igualdad le corresponderá informar y, en su caso, negociar las acciones de información, formación y difusión de las medidas de prevención del acoso sexual y por razón de sexo en el ámbito correspondiente, con la finalidad de conseguir mayor eficacia en la aplicación del protocolo y lograr una mayor seguridad __________ para las víctimas.","o":["laboral","personal","jurídica","psicológica"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">jurídica</mark></span>En el <span class=\"ref-norma\">apdo. V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"lograr una mayor seguridad jurídica para las víctimas\"</span>. Se persigue una mayor seguridad jurídica para las víctimas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1335","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. El asesor o asesora confidencial es la persona que, previa y específicamente __________ para ello, asistirá a la víctima que presente o quiera presentar una comunicación de activación del protocolo.","o":["designada","acreditada","formada","seleccionada"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">formada</mark></span>En el <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"previa y específicamente formada para ello\"</span>. Se define como la persona previa y específicamente formada para ello. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres","q":[{"i":"16-4","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Plan de Igualdad en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. El cumplimiento del Plan será evaluado anualmente por:","o":["El Gobierno","La Administración General del Estado.","El Consejo de Ministros.","El Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"y su cumplimiento será evaluado anualmente por el Consejo de Ministros.\"</span>. El Plan lo aprueba el Gobierno, pero su cumplimiento lo evalúa el Consejo de Ministros, anualmente."},{"i":"16-6","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre Mujeres y Hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. Este Plan será objeto de negociación con:","o":["Las organizaciones sindicales y empresariales con representatividad en la Administración General del Estado.","Por ser sus destinatarios, con los mismos organismos públicos vinculados o dependientes de la Administración General del Estado.","Los agentes sociales, las asociaciones de mujeres y otras entidades privadas cuyo objeto o finalidad sea la efectividad del derecho constitucional de igualdad entre mujeres y hombres.","La representación legal de los empleados públicos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La representación legal de los empleados públicos</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Plan será objeto de negociación, y en su caso acuerdo, con la representación legal de los empleados públicos en la forma que se determine en la legislación sobre negociación colectiva en la Administración Pública\"</span>"},{"i":"16-44","p":"LO 3/2007 - Acciones Positivas Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Con el fin de hacer efectivo el derecho constitucional de la igualdad, ¿quiénes adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres?","o":["Las personas privadas.","Los Poderes Públicos.","Las personas jurídicas públicas.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Poderes Públicos</mark></span>El <span class=\"ref-norma\">art. 11.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"los Poderes Públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.\"</span>. Las personas privadas «podrán» adoptarlas (art. 11.2); los Poderes Públicos «adoptarán»."},{"i":"16-46","p":"LO 3/2007 - Normas de Aplicación en Fuerzas y Cuerpos de Seguridad Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Las normas referidas al personal al servicio de las Administraciones Públicas en materia de igualdad, prevención de la violencia de género y la violencia sexual y conciliación de la vida ______ serán de aplicación en las Fuerzas y Cuerpos de Seguridad.","o":["Personal, familiar y profesional.","Laboral, personal y profesional.","Laboral, familiar y personal.","Profesional, familiar y laboral."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Personal, familiar y profesional</mark></span>El <span class=\"ref-norma\">art. 68 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Las normas referidas al personal al servicio de las administraciones públicas en materia de igualdad, prevención de la violencia de género y la violencia sexual, y la conciliación de la vida personal, familiar y profesional serán de aplicación en las Fuerzas y Cuerpos de Seguridad, adaptándose, en su caso, a las peculiaridades de las funciones que tienen encomendadas, en los términos establecidos por su normativa específica.\"</span>. La fórmula es «conciliación de la vida personal, familiar y profesional» (no «laboral»)."},{"i":"16-73","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Se considera discriminación directa por razón de sexo:","o":["Cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.","La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro.","La situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.","Toda orden de discriminar, únicamente de forma directa, por razón de sexo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable</mark></span>El <span class=\"ref-norma\">art. 6.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"1. Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.\"</span>"},{"i":"16-125","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Se considera discriminación indirecta por razón de sexo:","o":["La situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.","La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.","Cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.","Cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados</mark></span>El <span class=\"ref-norma\">art. 6.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.\"</span>"},{"i":"16-143","p":"Ley Orgánica 3/2007. El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre Mujeres y Hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. Este Plan será objeto de negociación con:","o":["Las organizaciones sindicales y empresariales con representatividad en la Administración General del Estado.","Por ser una destinataria, con los mismos organismos públicos vinculados o dependientes de la Administración General del Estado.","Los agentes sociales, las asociaciones de mujeres y otras entidades privadas cuyo objeto o finalidad sea la efectividad del derecho constitucional de igualdad entre mujeres y hombres.","La representación legal de los empleados públicos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La representación legal de los empleados públicos</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Plan será objeto de negociación, y en su caso acuerdo, con la representación legal de los empleados públicos en la forma que se determine en la legislación sobre negociación colectiva en la Administración Pública\"</span>"},{"i":"16-145","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Las normas referidas al personal al servicio de las administraciones públicas en materia de igualdad, prevención de la violencia de género y la violencia sexual, y la conciliación de la vida personal, familiar y profesional serán de aplicación, adaptándose, en su caso, a las peculiaridades de las funciones que tienen encomendadas, en los términos establecidos por su normativa específica:","o":["En las Fuerzas y Cuerpos de Seguridad.","En la empresa privada.","En las instituciones culturales y educativas, públicas y privadas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En las Fuerzas y Cuerpos de Seguridad</mark></span>El <span class=\"ref-norma\">art. 68 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Las normas referidas al personal al servicio de las administraciones públicas en materia de igualdad, prevención de la violencia de género y la violencia sexual, y la conciliación de la vida personal, familiar y profesional serán de aplicación en las Fuerzas y Cuerpos de Seguridad, adaptándose, en su caso, a las peculiaridades de las funciones que tienen encomendadas, en los términos establecidos por su normativa específica.\"</span>"},{"i":"16-150","p":"Ley Orgánica 3/2007. ¿Quién evaluará el cumplimiento del Plan para la igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella?","o":["El Consejo de Ministros.","El Gobierno.","El Ministerio de Justicia.","El Ministerio del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"y su cumplimiento será evaluado anualmente por el Consejo de Ministros.\"</span>. Ojo: el Plan lo APRUEBA «el Gobierno» (art. 64) y su cumplimiento lo EVALÚA «el Consejo de Ministros»."},{"i":"16-151","p":"Ley Orgánica 3/2007. El Gobierno aprobará, al inicio de cada legislatura, un Plan para la igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. El Plan establecerá los objetivos a alcanzar en materia de:","o":["Igualdad en las condiciones laborales, especialmente en materia retributiva.","Promoción de la igualdad de trato y oportunidades en el empleo público, así como las estrategias o medidas a adoptar para su consecución.","Promoción de la ocupación paritaria en los puestos de responsabilidad de la Administración.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Promoción de la igualdad de trato y oportunidades en el empleo público, así como las estrategias o medidas a adoptar para su consecución</mark></span>El <span class=\"ref-norma\">art. 64 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El Plan establecerá los objetivos a alcanzar en materia de promoción de la igualdad de trato y oportunidades en el empleo público, así como las estrategias o medidas a adoptar para su consecución.\"</span>. Solo la opción B reproduce el contenido legal del Plan; A y C añaden objetivos que el artículo no menciona."},{"i":"16-ia-1011","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Discriminación directa e indirecta. Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera __________ que otra en situación comparable.","o":["desfavorable","distinta","menos favorable","menos ventajosa, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">menos favorable</mark></span>El <span class=\"ref-norma\">art. 6.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"de manera menos favorable que otra en situación comparable\"</span>. La definición literal habla de un trato menos favorable que otra persona en situación comparable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1012","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Discriminación directa e indirecta. Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean:","o":["necesarios y proporcionados.","necesarios y adecuados.","adecuados y proporcionados.","razonables y necesarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">necesarios y adecuados</mark></span>El <span class=\"ref-norma\">art. 6.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"que los medios para alcanzar dicha finalidad sean necesarios y adecuados\"</span>. Los medios han de ser necesarios y adecuados para alcanzar la finalidad legítima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1023","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acciones positivas. Con el fin de hacer efectivo el derecho constitucional de la igualdad, los Poderes Públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres. Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser __________ en relación con el objetivo perseguido en cada caso.","o":["razonables y necesarias","proporcionadas y temporales, previo informe de la unidad policial competente.","razonables y proporcionadas","razonables y adecuadas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">razonables y proporcionadas</mark></span>El <span class=\"ref-norma\">art. 11.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso\"</span>. Las medidas de acción positiva han de ser razonables y proporcionadas en relación con el objetivo perseguido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1024","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acciones positivas. Respecto de las medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho:","o":["solo podrán adoptarlas los Poderes Públicos, en ejercicio de sus competencias.","también las personas físicas y jurídicas privadas podrán adoptar este tipo de medidas en los términos establecidos en la Ley.","las personas privadas podrán adoptarlas en todo caso, sin necesidad de ajustarse a lo establecido en la Ley, sin perjuicio de lo previsto en la normativa vigente.","las personas jurídicas privadas podrán adoptarlas, pero no las personas físicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">también las personas físicas y jurídicas privadas podrán adoptar este tipo de medidas en los términos establecidos en la Ley</mark></span>El <span class=\"ref-norma\">art. 11.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"También las personas físicas y jurídicas privadas podrán adoptar este tipo de medidas en los términos establecidos en la presente Ley\"</span>. Las personas físicas y jurídicas privadas también pueden adoptar medidas de acción positiva, en los términos de la Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1025","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acciones positivas. Señale la INCORRECTA respecto de las acciones positivas previstas en la Ley:","o":["Las medidas tendrán carácter permanente, aunque desaparezcan las situaciones de desigualdad de hecho que las motivaron.","Los Poderes Públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.","Las medidas serán aplicables en tanto subsistan dichas situaciones.","Las medidas habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las medidas tendrán carácter permanente, aunque desaparezcan las situaciones de desigualdad de hecho que las motivaron</mark></span>El <span class=\"ref-norma\">art. 11 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Tales medidas, que serán aplicables en tanto subsistan dichas situaciones\"</span>. Las medidas son aplicables solo mientras subsistan las situaciones patentes de desigualdad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1042","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Plan Estratégico de Igualdad de Oportunidades. El Gobierno, en las materias que sean de la competencia del Estado, aprobará periódicamente un:","o":["Plan Nacional de Igualdad de Oportunidades, que incluirá medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo, previo informe de la unidad policial competente.","Plan Estratégico para la Igualdad Efectiva, que incluirá medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y erradicar la violencia de género.","Plan Estratégico de Igualdad de Oportunidades, que incluirá medidas de acción positiva para corregir las situaciones patentes de desigualdad de hecho.","Plan Estratégico de Igualdad de Oportunidades, que incluirá medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Plan Estratégico de Igualdad de Oportunidades, que incluirá medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 17 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"aprobará periódicamente un Plan Estratégico de Igualdad de Oportunidades, que incluirá medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo\"</span>. El Gobierno aprueba periódicamente el Plan Estratégico de Igualdad de Oportunidades; no confundir con el Plan para la Igualdad en la AGE del art. 64, que se aprueba al inicio de cada legislatura. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1045","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Adecuación de las estadísticas y estudios. Al objeto de hacer efectivas las disposiciones de esta Ley y que se garantice la integración de modo efectivo de la perspectiva de género en su actividad ordinaria, los poderes públicos, en la elaboración de sus estudios y estadísticas, deberán incluir sistemáticamente:","o":["la variable de sexo en las estadísticas, encuestas y recogida de datos que lleven a cabo.","la variable de género en las estadísticas y registros administrativos que lleven a cabo, sin perjuicio de lo previsto en la normativa vigente.","la variable de sexo en las estadísticas, aunque no en las encuestas.","indicadores de sexo y edad en los registros que gestionen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la variable de sexo en las estadísticas, encuestas y recogida de datos que lleven a cabo</mark></span>El <span class=\"ref-norma\">art. 20.a de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Incluir sistemáticamente la variable de sexo en las estadísticas, encuestas y recogida de datos que lleven a cabo\"</span>. Se incluye sistemáticamente la variable de sexo en estadísticas, encuestas y recogida de datos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1046","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Adecuación de las estadísticas y estudios. Los poderes públicos, en la elaboración de sus estudios y estadísticas, deberán realizar muestras lo suficientemente __________ como para que las diversas variables incluidas puedan ser explotadas y analizadas en función de la variable de sexo.","o":["representativas","extensas","numerosas","amplias"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">amplias</mark></span>El <span class=\"ref-norma\">art. 20.d de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Realizar muestras lo suficientemente amplias como para que las diversas variables incluidas puedan ser explotadas y analizadas en función de la variable de sexo\"</span>. Las muestras han de ser lo suficientemente amplias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1047","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Adecuación de las estadísticas y estudios. Sólo excepcionalmente, y mediante informe __________ y aprobado por el órgano competente, podrá justificarse el incumplimiento de alguna de las obligaciones anteriormente especificadas en materia de estudios y estadísticas.","o":["previo","razonado","motivado","favorable"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">motivado</mark></span>El <span class=\"ref-norma\">art. 20 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Sólo excepcionalmente, y mediante informe motivado y aprobado por el órgano competente, podrá justificarse el incumplimiento de alguna de las obligaciones anteriormente especificadas\"</span>. El incumplimiento solo se justifica excepcionalmente mediante informe motivado y aprobado por el órgano competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1105","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Titulares de órganos directivos. El Gobierno atenderá al principio de presencia equilibrada de mujeres y hombres en el nombramiento de las personas titulares de los órganos directivos de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella, considerados:","o":["en su conjunto, cuya designación le corresponda.","individualmente, cuya designación le corresponda.","en su conjunto, cualquiera que sea la autoridad que los designe.","por departamentos ministeriales, cuya designación le corresponda."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en su conjunto, cuya designación le corresponda</mark></span>El <span class=\"ref-norma\">art. 52 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"considerados en su conjunto, cuya designación le corresponda\"</span>. La presencia equilibrada se aprecia en su conjunto y solo respecto de los órganos directivos cuya designación corresponda al Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1106","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Órganos de selección y Comisiones de valoración. Todos los tribunales y órganos de selección del personal de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella responderán al principio de presencia equilibrada de mujeres y hombres, salvo por razones:","o":["fundadas y excepcionales, debidamente justificadas.","objetivas y urgentes, debidamente motivadas.","organizativas y objetivas, debidamente acreditadas.","fundadas y objetivas, debidamente motivadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">fundadas y objetivas, debidamente motivadas</mark></span>El <span class=\"ref-norma\">art. 53 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"salvo por razones fundadas y objetivas, debidamente motivadas\"</span>. La excepción exige razones fundadas y objetivas, debidamente motivadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1107","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Órganos de selección y Comisiones de valoración. La representación de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella en las comisiones de valoración de méritos para la provisión de puestos de trabajo se ajustará al principio de:","o":["presencia equilibrada de mujeres y hombres, salvo razones fundadas y objetivas.","paridad entre ambos sexos.","composición equilibrada de ambos sexos.","representación proporcional de ambos sexos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">composición equilibrada de ambos sexos</mark></span>El <span class=\"ref-norma\">art. 53 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"se ajustará al principio de composición equilibrada de ambos sexos\"</span>. Para las comisiones de valoración de méritos el texto habla de composición equilibrada de ambos sexos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1126","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Plan de Igualdad en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella. El Gobierno aprobará, __________, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella.","o":["con carácter anual, salvo que la autoridad judicial disponga otra cosa.","cada cuatro años","periódicamente","al inicio de cada legislatura"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al inicio de cada legislatura</mark></span>El <span class=\"ref-norma\">art. 64 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres\"</span>. El Plan se aprueba al inicio de cada legislatura; el Plan Estratégico de Igualdad de Oportunidades se aprueba periódicamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1130","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Respeto del principio de igualdad. Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación __________, especialmente, en el sistema de acceso, formación, ascensos, destinos y situaciones administrativas.","o":["laboral","retributiva, en los términos que se determinen reglamentariamente.","salarial","profesional"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">profesional</mark></span>El <span class=\"ref-norma\">art. 67 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"impidiendo cualquier situación de discriminación profesional\"</span>. Se impide cualquier situación de discriminación profesional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1131","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Aplicación de las normas referidas al personal de las administraciones públicas en las Fuerzas y Cuerpos de Seguridad. Las normas referidas al personal al servicio de las administraciones públicas en materia de igualdad, __________ de la violencia de género y la violencia sexual, y la conciliación de la vida personal, familiar y profesional serán de aplicación en las Fuerzas y Cuerpos de Seguridad, adaptándose, en su caso, a las peculiaridades de las funciones que tienen encomendadas, en los términos establecidos por su normativa específica.","o":["protección integral contra la violencia","erradicación","prevención","lucha"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">prevención</mark></span>El <span class=\"ref-norma\">art. 68 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"en materia de igualdad, prevención de la violencia de género y la violencia sexual\"</span>. En las Fuerzas y Cuerpos de Seguridad se habla de «prevención de la violencia de género y la violencia sexual». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1132","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Aplicación de las normas referidas al personal de las administraciones públicas en las Fuerzas y Cuerpos de Seguridad. Las normas sobre igualdad, prevención de la violencia de género y la violencia sexual y conciliación serán de aplicación en las Fuerzas y Cuerpos de Seguridad, adaptándose, en su caso, a las __________ de las funciones que tienen encomendadas, en los términos establecidos por su normativa específica.","o":["necesidades","peculiaridades","particularidades","exigencias"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">peculiaridades</mark></span>El <span class=\"ref-norma\">art. 68 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"adaptándose, en su caso, a las peculiaridades de las funciones que tienen encomendadas\"</span>. El texto habla de las peculiaridades de las funciones encomendadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 19 — Informes de impacto de género","q":[{"i":"16-7","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación ______________ deberán incorporar un informe sobre su impacto por razón de género.","o":["Del Consejo de Ministros.","De las Cortes Generales.","Del Ministerio de Igualdad.","Del Congreso de los Diputados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 19 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación del Consejo de Ministros deberán incorporar un informe sobre su impacto por razón de género.\"</span>"},{"i":"16-144","p":"Ley Orgánica 3/2007. Los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación ______ deberán incorporar un informe sobre su impacto por razón de género.","o":["Del Consejo de Ministros.","De las Cortes Generales.","Del Ministerio de Igualdad.","Del Congreso de los Diputados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 19 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación del Consejo de Ministros deberán incorporar un informe sobre su impacto por razón de género.\"</span>"},{"i":"16-ia-1044","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Informes de impacto de género. Los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación del Consejo de Ministros deberán incorporar:","o":["un informe sobre su impacto en la igualdad de oportunidades.","un informe sobre su impacto por razón de género.","un informe preceptivo del Instituto de las Mujeres.","una memoria sobre su incidencia en la igualdad de trato."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un informe sobre su impacto por razón de género</mark></span>El <span class=\"ref-norma\">art. 19 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"deberán incorporar un informe sobre su impacto por razón de género\"</span>. Deben incorporar un informe sobre su impacto por razón de género. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 — Acciones de planificación equitativa de los tiempos ✱","q":[{"i":"16-11","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad efectiva de Mujeres y Hombres. Con el fin de avanzar hacia un reparto equitativo de los tiempos entre mujeres y hombres, las corporaciones locales podrán establecer ____________ de organización del tiempo de la ciudad.","o":["Planes Municipales.","Planes Provinciales.","Planes Autonómicos.","Planes Estatales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Planes Municipales</mark></span>El <span class=\"ref-norma\">art. 22 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"las corporaciones locales podrán establecer Planes Municipales de organización del tiempo de la ciudad.\"</span>"},{"i":"16-133","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Con el fin de avanzar hacia un reparto equitativo de los tiempos entre mujeres y hombres, las corporaciones locales podrán establecer Planes ______ de organización del tiempo de la ciudad.","o":["Nacionales.","Estatales.","Autonómicos.","Municipales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Municipales</mark></span>El <span class=\"ref-norma\">art. 22 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"las corporaciones locales podrán establecer Planes Municipales de organización del tiempo de la ciudad.\"</span>"},{"i":"16-142","p":"Ley Orgánica 3/2007. Con el fin de avanzar hacia un reparto equitativo de los tiempos entre mujeres y hombres, las corporaciones locales podrán establecer Planes ______ de organización del tiempo de la ciudad.","o":["Nacionales.","Estatales.","Autonómicos.","Municipales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Municipales</mark></span>El <span class=\"ref-norma\">art. 22 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"las corporaciones locales podrán establecer Planes Municipales de organización del tiempo de la ciudad.\"</span>"},{"i":"16-ia-1049","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acciones de planificación equitativa de los tiempos. Con el fin de avanzar hacia un reparto equitativo de los tiempos entre mujeres y hombres, las corporaciones locales podrán establecer Planes Municipales de organización del tiempo de la ciudad. Sin perjuicio de las competencias de las Comunidades Autónomas, el Estado podrá prestar __________ para la elaboración de estos planes.","o":["asistencia técnica","apoyo económico","asesoramiento jurídico","cooperación técnica y financiera"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">asistencia técnica</mark></span>El <span class=\"ref-norma\">art. 22 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"el Estado podrá prestar asistencia técnica para la elaboración de estos planes\"</span>. El Estado puede prestar asistencia técnica para la elaboración de los Planes Municipales de organización del tiempo de la ciudad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Indemnidad frente a represalias ✱","q":[{"i":"16-14","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. El principio de igualdad y la tutela contra la discriminación. Se considerará discriminación por razón de sexo cualquier trato adverso o efecto negativo que se produzca en una persona como consecuencia de la presentación por su parte de:","o":["Queja, reclamación, denuncia o recurso.","Queja, reforma, denuncia o recurso.","Queja, reclamación, denuncia, demanda o recurso.","Ninguna opción es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Queja, reclamación, denuncia, demanda o recurso</mark></span>El <span class=\"ref-norma\">art. 9 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"También se considerará discriminación por razón de sexo cualquier trato adverso o efecto negativo que se produzca en una persona como consecuencia de la presentación por su parte de queja, reclamación, denuncia, demanda o recurso, de cualquier tipo, destinados a impedir su discriminación y a exigir el cumplimiento efectivo del principio de igualdad de trato entre mujeres y hombres.\"</span>. La lista legal incluye también la «demanda» (queja, reclamación, denuncia, demanda o recurso)."},{"i":"16-ia-1020","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Indemnidad frente a represalias. También se considerará discriminación por razón de sexo cualquier trato adverso o efecto negativo que se produzca en una persona como consecuencia de la presentación por su parte de __________, de cualquier tipo, destinados a impedir su discriminación y a exigir el cumplimiento efectivo del principio de igualdad de trato entre mujeres y hombres.","o":["queja, reclamación, denuncia, demanda o solicitud","queja, reclamación, denuncia, demanda o recurso","queja, denuncia, demanda, recurso o petición","queja, reclamación, denuncia, querella o recurso"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">queja, reclamación, denuncia, demanda o recurso</mark></span>El <span class=\"ref-norma\">art. 9 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"como consecuencia de la presentación por su parte de queja, reclamación, denuncia, demanda o recurso, de cualquier tipo\"</span>. La enumeración es queja, reclamación, denuncia, demanda o recurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Objeto de la Ley","q":[{"i":"16-15","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. Las mujeres y los hombres son iguales en dignidad humana, e iguales en _______________.","o":["Derechos y deberes.","Libertades.","Derechos y responsabilidades.","Ninguna opción es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Derechos y deberes</mark></span>El <span class=\"ref-norma\">art. 1.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Las mujeres y los hombres son iguales en dignidad humana, e iguales en derechos y deberes.\"</span>"},{"i":"16-ia-1001","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Objeto de la Ley. Las mujeres y los hombres son iguales en dignidad humana, e iguales en derechos y deberes. Esta Ley tiene por objeto hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres, en particular mediante la eliminación de la discriminación de la mujer, sea cual fuere su circunstancia o condición, en cualesquiera de los ámbitos de la vida y, singularmente, en las esferas __________.","o":["política, civil, laboral, económica, social y cultural","política, civil, laboral, económica, jurídica y cultural","política, civil, laboral, educativa, social y cultural","política, administrativa, laboral, económica, social y cultural"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">política, civil, laboral, económica, social y cultural</mark></span>El <span class=\"ref-norma\">art. 1.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"singularmente, en las esferas política, civil, laboral, económica, social y cultural\"</span>. Las esferas citadas son la política, civil, laboral, económica, social y cultural; no se mencionan la jurídica, la educativa ni la administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1002","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Objeto de la Ley. Esta Ley tiene por objeto hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres, en particular mediante la eliminación de la discriminación de la mujer, para, en el desarrollo de los preceptos constitucionales de la igualdad real y de la igualdad ante la ley, alcanzar una sociedad:","o":["más democrática, más justa y más igualitaria.","más justa, más solidaria y más igualitaria.","más democrática, más plural y más solidaria.","más democrática, más justa y más solidaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">más democrática, más justa y más solidaria</mark></span>El <span class=\"ref-norma\">art. 1.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"alcanzar una sociedad más democrática, más justa y más solidaria\"</span>. La finalidad es alcanzar una sociedad más democrática, más justa y más solidaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Acoso sexual y acoso por razón de sexo EX ✱","q":[{"i":"16-19","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. Señale la correcta sobre el acoso sexual y el acoso por razón de sexo.","o":["Constituye acoso por razón de sexo cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.","El condicionamiento de un derecho o de una expectativa de derecho a la aceptación de una situación constitutiva de acoso sexual o de acoso por razón de sexo se considerará también acto de discriminación por razón de sexo.","Constituye acoso sexual cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El condicionamiento de un derecho o de una expectativa de derecho a la aceptación de una situación constitutiva de acoso sexual o de acoso por razón de sexo se considerará también acto de discriminación por razón de sexo</mark></span>El <span class=\"ref-norma\">art. 7.4 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"4. El condicionamiento de un derecho o de una expectativa de derecho a la aceptación de una situación constitutiva de acoso sexual o de acoso por razón de sexo se considerará también acto de discriminación por razón de sexo.\"</span>. La opción A atribuye al acoso por razón de sexo la definición del acoso sexual, y la C hace lo contrario; solo B es literal."},{"i":"16-20","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. Sin perjuicio de lo establecido en ______________ a los efectos de esta Ley constituye acoso sexual a cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.","o":["El Código Penal.","El Código Civil.","La Ley Orgánica de Medidas de Protección Integral contra la Violencia de Género.","Ninguna opción es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Código Penal</mark></span>El <span class=\"ref-norma\">art. 7.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"1. Sin perjuicio de lo establecido en el Código Penal, a los efectos de esta Ley constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-27","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno:","o":["Intimidatorio, ofensivo o humillante.","Humillante, ofensivo o degradante.","Degradante, humillante o intimidatorio.","Intimidatorio, degradante u ofensivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Intimidatorio, degradante u ofensivo</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-69","p":"(LO 3/2007 - LOIG) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno:","o":["Intimidatorio, ofensivo o humillante.","Humillante, ofensivo o degradante.","Degradante, humillante o intimidatorio.","Intimidatorio, degradante u ofensivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Intimidatorio, degradante u ofensivo</mark></span>El <span class=\"ref-norma\">art. 7.2 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"2. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-86","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Sin perjuicio de lo establecido en el Código Penal, a los efectos de esta Ley, cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo, constituye:","o":["Acoso por razón de sexo.","Acoso sexual.","Discriminación indirecta por razón de sexo.","Discriminación por embarazo o maternidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Acoso sexual</mark></span>El <span class=\"ref-norma\">art. 7.1 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"1. Sin perjuicio de lo establecido en el Código Penal, a los efectos de esta Ley constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo.\"</span>"},{"i":"16-ia-1014","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acoso sexual y acoso por razón de sexo. Sin perjuicio de lo establecido en el Código Penal, a los efectos de esta Ley constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno:","o":["intimidatorio, hostil o humillante, en los términos que se determinen reglamentariamente.","intimidatorio, degradante o hostil.","hostil, degradante u ofensivo.","intimidatorio, degradante u ofensivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">intimidatorio, degradante u ofensivo</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"en particular cuando se crea un entorno intimidatorio, degradante u ofensivo\"</span>. El entorno es intimidatorio, degradante u ofensivo; hostil o humillante aparecen en el Código Penal, no en la LO 3/2007. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1015","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acoso sexual y acoso por razón de sexo. Constituye acoso por razón de sexo cualquier comportamiento realizado en __________ de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.","o":["atención al sexo","razón del género","función del sexo","función de la condición"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">función del sexo</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"cualquier comportamiento realizado en función del sexo de una persona\"</span>. El acoso por razón de sexo es el comportamiento realizado en función del sexo de una persona. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1016","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Acoso sexual y acoso por razón de sexo. El acoso sexual y el acoso por razón de sexo se diferencian en que:","o":["el primero exige un comportamiento físico de naturaleza sexual, y el segundo, un comportamiento verbal realizado en función del sexo de la persona.","el primero exige un comportamiento, verbal o físico, de naturaleza sexual, y el segundo, un comportamiento realizado en función del sexo de la persona.","el primero exige un comportamiento reiterado de naturaleza sexual, y el segundo, un comportamiento puntual realizado en función del sexo de la persona.","el primero exige un comportamiento de naturaleza sexual con ánimo libidinoso, y el segundo, un comportamiento realizado en función del género de la persona."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el primero exige un comportamiento, verbal o físico, de naturaleza sexual, y el segundo, un comportamiento realizado en función del sexo de la persona</mark></span>El <span class=\"ref-norma\">art. 7.1-2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona\"</span>. El acoso sexual se define por la naturaleza sexual del comportamiento (verbal o físico) y el acoso por razón de sexo, por realizarse en función del sexo de una persona. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 59 — Vacaciones","q":[{"i":"16-21","p":"Ley Orgánica 3/2007, de 22 de marzo, para la Igualdad Efectiva de Mujeres y Hombres. Sin perjuicio de las mejoras que pudieran derivarse de acuerdos suscritos entre la Administración General del Estado o los organismos públicos vinculados o dependientes de ella con la representación de los empleados y empleadas al servicio de la Administración Pública, cuando el período de vacaciones coincida con una incapacidad temporal derivada ______________ o con el permiso de maternidad, o con su ampliación por lactancia, la empleada pública tendrá derecho a disfrutar las vacaciones en fecha distinta, aunque haya terminado el año natural al que correspondan.","o":["De embarazo.","De enfermedad común.","De accidente laboral.","Ninguna opción es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De embarazo</mark></span>El <span class=\"ref-norma\">art. 59 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"cuando el periodo de vacaciones coincida con una incapacidad temporal derivada del embarazo, parto o lactancia natural, o con el permiso de maternidad, o con su ampliación por lactancia, la empleada pública tendrá derecho a disfrutar las vacaciones en fecha distinta, aunque haya terminado el año natural al que correspondan.\"</span>"},{"i":"16-ia-1115","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Vacaciones. Cuando el periodo de vacaciones coincida con una incapacidad temporal derivada del embarazo, parto o lactancia natural, o con el permiso de maternidad, o con su ampliación por lactancia, la empleada pública tendrá derecho a disfrutar las vacaciones en fecha distinta, aunque haya terminado:","o":["el período de incapacidad temporal.","el curso o ejercicio en que se produjo la coincidencia.","el año natural al que correspondan.","el plazo de seis meses desde su devengo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el año natural al que correspondan</mark></span>El <span class=\"ref-norma\">art. 59 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"aunque haya terminado el año natural al que correspondan\"</span>. Puede disfrutarlas aunque haya terminado el año natural al que correspondan. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1116","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Vacaciones. Quienes estén disfrutando de permiso de paternidad gozarán del mismo derecho que la empleada pública a:","o":["disfrutar las vacaciones en fecha distinta, pero solo dentro del año natural al que correspondan, sin perjuicio de lo previsto en la normativa vigente.","disfrutar las vacaciones en fecha distinta, aunque haya terminado el año natural al que correspondan.","acumular las vacaciones al permiso de paternidad, hasta un máximo de quince días.","disfrutar las vacaciones durante el año siguiente, previa autorización de la unidad de personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">disfrutar las vacaciones en fecha distinta, aunque haya terminado el año natural al que correspondan</mark></span>El <span class=\"ref-norma\">art. 59 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Gozarán de este mismo derecho quienes estén disfrutando de permiso de paternidad\"</span>. El mismo derecho de disfrutar las vacaciones en fecha distinta, aunque haya terminado el año natural, alcanza a quienes disfruten de permiso de paternidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 — Criterios generales de actuación de los Poderes Públicos EXOF ✱","q":[{"i":"16-31","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. A los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos (señale la opción INCORRECTA):","o":["La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.","La consideración de las singulares dificultades en que se encuentran las mujeres de colectivos de especial vulnerabilidad como son las que pertenecen a minorías, las mujeres migrantes, las niñas, las mujeres con discapacidad, las mujeres mayores, las mujeres viudas y las mujeres víctimas de violencia de género, para las cuales los poderes públicos podrán adoptar, igualmente, medidas de acción positiva.","El establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, así como el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia.","La protección de la paternidad, con especial atención a la asunción por la sociedad de los efectos derivados de la lactancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La protección de la paternidad, con especial atención a la asunción por la sociedad de los efectos derivados de la lactancia</mark></span>El <span class=\"ref-norma\">art. 14.7 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"6. La consideración de las singulares dificultades en que se encuentran las mujeres de colectivos de especial vulnerabilidad como son las que pertenecen a minorías, las mujeres migrantes, las niñas, las mujeres con discapacidad, las mujeres mayores, las mujeres viudas y las mujeres víctimas de violencia de género, para las cuales los poderes públicos podrán adoptar, igualmente, medidas de acción positiva. … 7. La protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia.\"</span>. Son dos las alteraciones del enunciado: «madres viudas» (es «mujeres viudas») y la «paternidad» en lugar de la «maternidad». Se deja solo la D como incorrecta."},{"i":"16-71","p":"(LO 3/2007 - LOIG) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. A los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos (señale la opción INCORRECTA):","o":["La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.","La consideración de las singulares dificultades en que se encuentran las mujeres de colectivos de especial vulnerabilidad como son las que pertenecen a minorías, las mujeres migrantes, las niñas, las mujeres con discapacidad, las mujeres mayores, las mujeres viudas y las mujeres víctimas de violencia de género, para las cuales los poderes públicos podrán adoptar, igualmente, medidas de acción positiva.","El establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, así como el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia.","La protección de la paternidad, con especial atención a la asunción por la sociedad de los efectos derivados de la lactancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La protección de la paternidad, con especial atención a la asunción por la sociedad de los efectos derivados de la lactancia</mark></span>El <span class=\"ref-norma\">art. 14.7 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"6. La consideración de las singulares dificultades en que se encuentran las mujeres de colectivos de especial vulnerabilidad como son las que pertenecen a minorías, las mujeres migrantes, las niñas, las mujeres con discapacidad, las mujeres mayores, las mujeres viudas y las mujeres víctimas de violencia de género, para las cuales los poderes públicos podrán adoptar, igualmente, medidas de acción positiva. … 7. La protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia.\"</span>. Son dos las alteraciones del enunciado: «madres viudas» (es «mujeres viudas») y la «paternidad» en lugar de la «maternidad». Se deja solo la D como incorrecta."},{"i":"16-77","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. A los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos, entre otras: señale la correcta.","o":["La implantación de un lenguaje no sexista únicamente en el ámbito educativo y su fomento en las relaciones laborales.","La participación equilibrada de mujeres y hombres únicamente en las candidaturas electorales.","El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares.","El fomento de instrumentos de colaboración entre las distintas Administraciones públicas, excluidos los agentes sociales y las asociaciones de mujeres."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares</mark></span>El <span class=\"ref-norma\">art. 14.10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"10. El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares.\"</span>"},{"i":"16-111","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. A los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos: señale la INCORRECTA.","o":["El compromiso con la efectividad del derecho constitucional de igualdad entre mujeres y hombres.","La participación equilibrada de mujeres y hombres en las candidaturas electorales y en la toma de decisiones.","La implantación de un lenguaje no sexista en el ámbito administrativo y su fomento en la totalidad de las relaciones sociales, culturales y artísticas.","El establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, sin incluir el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, sin incluir el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia</mark></span>El <span class=\"ref-norma\">art. 14.8 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"8. El establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, así como el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia.\"</span>"},{"i":"16-135","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Políticas públicas para la igualdad. La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo, es un criterio general de actuación de:","o":["El Gobierno.","La Administración General del Estado.","Los Poderes Públicos.","Los Ministerios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Poderes Públicos</mark></span>El <span class=\"ref-norma\">art. 14.5 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"5. La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.\"</span>"},{"i":"16-148","p":"Ley Orgánica 3/2007. A los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos: señale la INCORRECTA.","o":["La participación equilibrada de mujeres y hombres en las candidaturas electorales y en la toma de decisiones.","La protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia.","El fomento de instrumentos de colaboración entre las distintas Administraciones públicas y los agentes sociales, las asociaciones de mujeres y otras entidades privadas.","El fomento de la efectividad del principio de igualdad entre mujeres y hombres únicamente en las relaciones laborales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El fomento de la efectividad del principio de igualdad entre mujeres y hombres únicamente en las relaciones laborales</mark></span>El <span class=\"ref-norma\">art. 14.10 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"10. El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares.\"</span>. El fomento de la efectividad del principio de igualdad en las relaciones entre particulares SÍ es criterio del art. 14.10; la opción D lo restringe a las relaciones laborales y es la falsa."},{"i":"16-156","p":"Ley Orgánica 3/2007. Políticas públicas para la igualdad. La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo, es un criterio general de actuación de:","o":["El Gobierno.","La Administración General del Estado.","Los Poderes Públicos.","Los Ministerios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Poderes Públicos</mark></span>El <span class=\"ref-norma\">art. 14.5 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"5. La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.\"</span>"},{"i":"16-182","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos: la _____ entre las distintas Administraciones públicas en la aplicación del principio de igualdad de trato y de oportunidades.","o":["Colaboración y cooperación.","Coordinación y cooperación.","Colaboración y coordinación.","Cooperación y asistencia técnica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Colaboración y cooperación</mark></span>El <span class=\"ref-norma\">art. 14.3 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"La colaboración y cooperación entre las distintas Administraciones públicas en la aplicación del principio de igualdad de trato y de oportunidades\"</span>"},{"i":"16-ia-1032","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos la integración del principio de igualdad de trato y de oportunidades en el conjunto de las políticas económica, laboral, social, cultural y artística, con el fin de evitar la segregación laboral y eliminar las diferencias retributivas, así como potenciar el crecimiento del empresariado femenino en todos los ámbitos que abarque el conjunto de políticas y el valor del trabajo de las mujeres, incluido:","o":["el no remunerado.","el doméstico.","el de cuidados.","el rural."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el doméstico</mark></span>El <span class=\"ref-norma\">art. 14.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"el valor del trabajo de las mujeres, incluido el doméstico\"</span>. Se valora el trabajo de las mujeres, incluido el doméstico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1033","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos: la __________ entre las distintas Administraciones públicas en la aplicación del principio de igualdad de trato y de oportunidades.","o":["colaboración y cooperación","coordinación y cooperación","colaboración y coordinación","cooperación y asistencia"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">colaboración y cooperación</mark></span>El <span class=\"ref-norma\">art. 14.3 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"La colaboración y cooperación entre las distintas Administraciones públicas en la aplicación del principio de igualdad de trato y de oportunidades\"</span>. El criterio es la colaboración y cooperación entre Administraciones públicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1034","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos la participación equilibrada de mujeres y hombres en:","o":["las candidaturas electorales y en los órganos de dirección.","los órganos colegiados y en la toma de decisiones.","las listas electorales y en los puestos directivos de la Administración.","las candidaturas electorales y en la toma de decisiones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las candidaturas electorales y en la toma de decisiones</mark></span>El <span class=\"ref-norma\">art. 14.4 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"La participación equilibrada de mujeres y hombres en las candidaturas electorales y en la toma de decisiones\"</span>. Se trata de la participación equilibrada en las candidaturas electorales y en la toma de decisiones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1035","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Entre las mujeres de colectivos de especial vulnerabilidad a cuyas singulares dificultades deben atender los Poderes Públicos, adoptando, igualmente, medidas de acción positiva, NO se cita expresamente a:","o":["las mujeres viudas.","las mujeres mayores.","las mujeres desempleadas.","las mujeres migrantes, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las mujeres desempleadas</mark></span>El <span class=\"ref-norma\">art. 14.6 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"las que pertenecen a minorías, las mujeres migrantes, las niñas, las mujeres con discapacidad, las mujeres mayores, las mujeres viudas y las mujeres víctimas de violencia de género\"</span>. Se citan las minorías, migrantes, niñas, discapacidad, mayores, viudas y víctimas de violencia de género; no las desempleadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1036","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos la protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del __________.","o":["embarazo y parto","embarazo, parto y lactancia","parto y lactancia","embarazo, parto y crianza, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">embarazo, parto y lactancia</mark></span>El <span class=\"ref-norma\">art. 14.7 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia\"</span>. Los efectos derivados del embarazo, parto y lactancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1037","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Criterios generales de actuación de los Poderes Públicos. Serán criterios generales de actuación de los Poderes Públicos el establecimiento de medidas que aseguren la conciliación del trabajo y de la vida personal y familiar de las mujeres y los hombres, así como el fomento de la __________ en las labores domésticas y en la atención a la familia.","o":["corresponsabilidad","colaboración","participación","responsabilidad compartida"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">corresponsabilidad</mark></span>El <span class=\"ref-norma\">art. 14.8 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"así como el fomento de la corresponsabilidad en las labores domésticas y en la atención a la familia\"</span>. Se fomenta la corresponsabilidad en las labores domésticas y en la atención a la familia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 58 — Licencia por riesgo durante el embarazo y lactancia","q":[{"i":"16-39","p":"(LO 3/2007 - Igualdad Efectiva) Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. Cuando las condiciones del puesto de trabajo de una funcionaria incluida en el ámbito de aplicación del mutualismo administrativo pudieran influir negativamente en la salud de la mujer, del hijo o hija, podrá concederse licencia por riesgo durante el embarazo, en los mismos términos y condiciones previstas en la normativa aplicable. En estos casos, ¿durante cuánto tiempo se garantizará la plenitud de los derechos económicos de la funcionaria?","o":["Durante un máximo de cuatro meses.","Durante un máximo de tres meses.","Durante toda la duración de la licencia.","Durante un máximo de seis meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Durante toda la duración de la licencia</mark></span>El <span class=\"ref-norma\">art. 58 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"podrá concederse licencia por riesgo durante el embarazo, en los mismos términos y condiciones previstas en la normativa aplicable. En estos casos, se garantizará la plenitud de los derechos económicos de la funcionaria durante toda la duración de la licencia, de acuerdo con lo establecido en la legislación específica.\"</span>"},{"i":"16-126","p":"Texto: Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Cuando las condiciones del puesto de trabajo de una funcionaria incluida en el ámbito de aplicación del mutualismo administrativo pudieran influir negativamente en la salud de la mujer, del hijo e hija, podrá concederse:","o":["Vacaciones por riesgo durante el embarazo.","Permiso urgente por riesgo durante el embarazo.","Permiso de lactancia.","Licencia por riesgo durante el embarazo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Licencia por riesgo durante el embarazo</mark></span>El <span class=\"ref-norma\">art. 58 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"podrá concederse licencia por riesgo durante el embarazo, en los mismos términos y condiciones previstas en la normativa aplicable. En estos casos, se garantizará la plenitud de los derechos económicos de la funcionaria durante toda la duración de la licencia, de acuerdo con lo establecido en la legislación específica.\"</span>"},{"i":"16-134","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. ¿Qué podrá concederse cuando las condiciones del puesto de trabajo de una funcionaria incluida en el ámbito de aplicación del mutualismo administrativo pudieran influir negativamente en la salud de la mujer, del hijo e hija?","o":["Excedencia por riesgo durante el embarazo.","Permiso por riesgo durante el embarazo.","Permiso prorrogable por asuntos propios.","Licencia por riesgo durante el embarazo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Licencia por riesgo durante el embarazo</mark></span>El <span class=\"ref-norma\">art. 58 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"podrá concederse licencia por riesgo durante el embarazo, en los mismos términos y condiciones previstas en la normativa aplicable. En estos casos, se garantizará la plenitud de los derechos económicos de la funcionaria durante toda la duración de la licencia, de acuerdo con lo establecido en la legislación específica.\"</span>. El artículo habla de «licencia por riesgo durante el embarazo», no de excedencia ni de permiso."},{"i":"16-155","p":"Ley Orgánica 3/2007. ¿Qué podrá concederse cuando las condiciones del puesto de trabajo de una funcionaria incluida en el ámbito de aplicación del mutualismo administrativo pudieran influir negativamente en la salud de la mujer, del hijo e hija?","o":["Excedencia por riesgo durante el embarazo.","Permiso por riesgo durante el embarazo.","Permiso prorrogable por asuntos propios.","Licencia por riesgo durante el embarazo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Licencia por riesgo durante el embarazo</mark></span>El <span class=\"ref-norma\">art. 58 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"podrá concederse licencia por riesgo durante el embarazo, en los mismos términos y condiciones previstas en la normativa aplicable. En estos casos, se garantizará la plenitud de los derechos económicos de la funcionaria durante toda la duración de la licencia, de acuerdo con lo establecido en la legislación específica.\"</span>. El artículo habla de «licencia por riesgo durante el embarazo», no de excedencia ni de permiso."},{"i":"16-ia-1113","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Licencia por riesgo durante el embarazo y lactancia. Cuando las condiciones del puesto de trabajo de una funcionaria incluida en el ámbito de aplicación del mutualismo administrativo pudieran influir negativamente en la salud de la mujer, del hijo e hija, podrá concederse licencia por riesgo durante el embarazo. En estos casos, se garantizará la plenitud de los derechos __________ de la funcionaria durante toda la duración de la licencia.","o":["económicos","laborales","retributivos y de Seguridad Social","profesionales"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">económicos</mark></span>El <span class=\"ref-norma\">art. 58 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"se garantizará la plenitud de los derechos económicos de la funcionaria durante toda la duración de la licencia\"</span>. Se garantiza la plenitud de los derechos económicos durante toda la duración de la licencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1114","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Licencia por riesgo durante el embarazo y lactancia. Lo dispuesto sobre la licencia por riesgo durante el embarazo de las funcionarias incluidas en el ámbito de aplicación del mutualismo administrativo será también de aplicación durante el período de:","o":["lactancia, sea natural o artificial.","los doce meses siguientes al parto.","la excedencia por cuidado de hijo.","lactancia natural."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">lactancia natural</mark></span>El <span class=\"ref-norma\">art. 58 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"será también de aplicación durante el período de lactancia natural\"</span>. Se aplica también durante el período de lactancia natural. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 15 — Transversalidad del principio de igualdad de trato entre mujeres y hombres EXOF","q":[{"i":"16-45","p":"LO 3/2007 - Principio de Igualdad de Trato Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. El principio de igualdad de trato y oportunidades entre mujeres y hombres informará, con carácter ______ la actuación de todos los Poderes Públicos.","o":["Transversal.","Solidario.","Prioritario.","Especial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Transversal</mark></span>El <span class=\"ref-norma\">art. 15 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato y oportunidades entre mujeres y hombres informará, con carácter transversal, la actuación de todos los Poderes Públicos.\"</span>"},{"i":"16-ia-1039","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Transversalidad del principio de igualdad de trato entre mujeres y hombres. El principio de igualdad de trato y oportunidades entre mujeres y hombres informará, con carácter __________, la actuación de todos los Poderes Públicos.","o":["general","preferente, en los términos que se determinen reglamentariamente.","transversal","vinculante"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">transversal</mark></span>El <span class=\"ref-norma\">art. 15 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"informará, con carácter transversal, la actuación de todos los Poderes Públicos\"</span>. El principio informa con carácter transversal la actuación de todos los Poderes Públicos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1040","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Transversalidad del principio de igualdad de trato entre mujeres y hombres. Las Administraciones públicas integrarán de forma activa el principio de igualdad de trato y oportunidades entre mujeres y hombres en la adopción y ejecución de sus disposiciones normativas, en la definición y __________ de políticas públicas en todos los ámbitos y en el desarrollo del conjunto de todas sus actividades.","o":["evaluación","presupuestación","planificación, salvo que la autoridad judicial disponga otra cosa.","ejecución"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">presupuestación</mark></span>El <span class=\"ref-norma\">art. 15 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"en la definición y presupuestación de políticas públicas en todos los ámbitos\"</span>. Se integra en la definición y presupuestación de políticas públicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 16 — Nombramientos realizados por los Poderes Públicos","q":[{"i":"16-48","p":"LO 3/2007 - Principio de Presencia Equilibrada Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de hombres y mujeres. ¿Quién procurará atender al principio de presencia equilibrada de mujeres y hombres en los nombramientos y designaciones de los cargos de responsabilidad que les correspondan?","o":["El Gobierno.","Los Poderes Públicos.","Las entidades privadas.","Las entidades públicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Poderes Públicos</mark></span>El <span class=\"ref-norma\">art. 16 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"Los Poderes Públicos procurarán atender al principio de presencia equilibrada de mujeres y hombres en los nombramientos y designaciones de los cargos de responsabilidad que les correspondan.\"</span>"},{"i":"16-ia-1041","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Nombramientos realizados por los Poderes Públicos. Los Poderes Públicos procurarán atender al principio de presencia __________ de mujeres y hombres en los nombramientos y designaciones de los cargos de responsabilidad que les correspondan.","o":["equilibrada","paritaria","proporcional","efectiva"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">equilibrada</mark></span>El <span class=\"ref-norma\">art. 16 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Los Poderes Públicos procurarán atender al principio de presencia equilibrada de mujeres y hombres en los nombramientos y designaciones de los cargos de responsabilidad que les correspondan\"</span>. El principio es el de presencia equilibrada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 56 — Permisos y beneficios de protección a la maternidad y la conciliación de la vida personal, familiar y laboral ✱","q":[{"i":"16-74","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Sin perjuicio de las mejoras que pudieran derivarse de acuerdos suscritos entre la Administración General del Estado o los organismos públicos vinculados o dependientes de ella con los representantes del personal al servicio de la Administración Pública, la normativa aplicable a los mismos establecerá:","o":["Únicamente un régimen de permisos retribuidos con el fin de proteger la maternidad.","Un registro de excedencias y de permisos por maternidad en cada departamento ministerial.","Un régimen de excedencias, reducciones de jornada, permisos u otros beneficios con el fin de proteger la maternidad y facilitar la conciliación de la vida personal, familiar y laboral.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un régimen de excedencias, reducciones de jornada, permisos u otros beneficios con el fin de proteger la maternidad y facilitar la conciliación de la vida personal, familiar y laboral</mark></span>El <span class=\"ref-norma\">art. 56 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"la normativa aplicable a los mismos establecerá un régimen de excedencias, reducciones de jornada, permisos u otros beneficios con el fin de proteger la maternidad y facilitar la conciliación de la vida personal, familiar y laboral.\"</span>"},{"i":"16-ia-1111","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Permisos y beneficios de protección a la maternidad y la conciliación de la vida personal, familiar y laboral. La normativa aplicable al personal de la Administración General del Estado establecerá un régimen de excedencias, reducciones de jornada, permisos u otros beneficios con el fin de proteger la maternidad y facilitar la conciliación de la vida personal, familiar y laboral. Con la misma finalidad se reconocerá un permiso de __________, en los términos que disponga dicha normativa.","o":["maternidad","lactancia","paternidad","corresponsabilidad"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">paternidad</mark></span>El <span class=\"ref-norma\">art. 56 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"Con la misma finalidad se reconocerá un permiso de paternidad, en los términos que disponga dicha normativa\"</span>. El precepto reconoce, con la misma finalidad, un permiso de paternidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo ✱","q":[{"i":"16-80","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. El principio de igualdad de trato y de oportunidades entre mujeres y hombres, aplicable en el ámbito del empleo privado y en el del empleo público, se garantizará, en los términos previstos en la normativa aplicable:","o":["En el acceso al empleo, incluso al trabajo por cuenta propia.","En la formación profesional, en la promoción profesional y en las condiciones de trabajo, incluidas las retributivas y las de despido.","En la afiliación y participación en las organizaciones sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 5 de la Ley Orgánica 3/2007</span> dispone: <span class=\"ref-concepto\">\"El principio de igualdad de trato y de oportunidades entre mujeres y hombres, aplicable en el ámbito del empleo privado y en el del empleo público, se garantizará, en los términos previstos en la normativa aplicable, en el acceso al empleo, incluso al trabajo por cuenta propia, en la formación profesional, en la promoción profesional, en las condiciones de trabajo, incluidas las retributivas y las de despido, y en la afiliación y participación en las organizaciones sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas.\"</span>"},{"i":"16-179","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo. No constituirá discriminación en el acceso al empleo, incluida la formación necesaria, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional _____, siempre y cuando el objetivo sea legítimo y el requisito proporcionado.","o":["Esencial y objetivo.","Esencial y determinante.","Necesario y determinante.","Fundamental y proporcionado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Esencial y determinante</mark></span>El <span class=\"ref-norma\">art. 5 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"dicha característica constituya un requisito profesional esencial y determinante, siempre y cuando el objetivo sea legítimo y el requisito proporcionado\"</span>"},{"i":"16-ia-1008","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo. El principio de igualdad de trato y de oportunidades entre mujeres y hombres, aplicable en el ámbito del empleo privado y en el del empleo público, se garantizará, en los términos previstos en la normativa aplicable, en el acceso al empleo, incluso al trabajo por cuenta propia, en la formación profesional, en la promoción profesional, en las condiciones de trabajo, incluidas las retributivas y las de despido, y en la afiliación y participación en las organizaciones:","o":["sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, excluidas las prestaciones concedidas por las mismas, previo informe de la unidad policial competente.","sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas.","sindicales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas.","sindicales y empresariales, o en cualquier organización profesional con fines colegiales, incluidas las prestaciones concedidas por las mismas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas</mark></span>El <span class=\"ref-norma\">art. 5 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"y en la afiliación y participación en las organizaciones sindicales y empresariales, o en cualquier organización cuyos miembros ejerzan una profesión concreta, incluidas las prestaciones concedidas por las mismas\"</span>. Se incluyen las prestaciones concedidas por las organizaciones sindicales y empresariales o profesionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1009","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo. No constituirá discriminación en el acceso al empleo, incluida la formación necesaria, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional __________, siempre y cuando el objetivo sea legítimo y el requisito proporcionado.","o":["esencial y determinante","esencial y objetivo","necesario y determinante","esencial y razonable"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">esencial y determinante</mark></span>El <span class=\"ref-norma\">art. 5 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"dicha característica constituya un requisito profesional esencial y determinante, siempre y cuando el objetivo sea legítimo y el requisito proporcionado\"</span>. El requisito debe ser esencial y determinante, el objetivo legítimo y el requisito proporcionado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1010","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Igualdad de trato y de oportunidades en el acceso al empleo, en la formación y en la promoción profesionales, y en las condiciones de trabajo. Señale la INCORRECTA sobre las diferencias de trato basadas en el sexo en el acceso al empleo:","o":["No constituirá discriminación si la característica es un requisito profesional esencial y determinante debido a la naturaleza de las actividades profesionales concretas.","No constituirá discriminación si la característica es un requisito profesional esencial y determinante debido al contexto en el que se lleven a cabo las actividades.","Para que no constituya discriminación, el objetivo debe ser legítimo y el requisito proporcionado.","Constituye discriminación toda diferencia de trato basada en una característica relacionada con el sexo, sin excepción alguna."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Constituye discriminación toda diferencia de trato basada en una característica relacionada con el sexo, sin excepción alguna</mark></span>El <span class=\"ref-norma\">art. 5 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"No constituirá discriminación en el acceso al empleo, incluida la formación necesaria, una diferencia de trato basada en una característica relacionada con el sexo cuando, debido a la naturaleza de las actividades profesionales concretas o al contexto en el que se lleven a cabo, dicha característica constituya un requisito profesional esencial y determinante\"</span>. La Ley admite una excepción: la característica relacionada con el sexo que sea requisito profesional esencial y determinante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Real Decreto 247/2024 · Preámbulo","q":[{"i":"16-97","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Inicio de las actuaciones. Las actuaciones previstas en este protocolo se inician por la remisión de una comunicación (verbal o escrita) a la unidad receptora. La comunicación, a través de los canales establecidos, podrá ser presentada por: señale la INCORRECTA.","o":["La persona presuntamente acosada (víctima) y/o por su representante legal.","La representación de las empleadas y empleados públicos en el ámbito en donde aquellos presten sus servicios.","Cualquier empleada y empleado público que tuviera conocimiento de situaciones que pudieran ser constitutivas de acoso sexual y/o de acoso por razón de sexo.","Únicamente la persona presuntamente acosada (víctima)."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Únicamente la persona presuntamente acosada (víctima)</mark></span>El <span class=\"ref-norma\">apartado 4.2 del Real Decreto 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"La comunicación, a través de los canales establecidos, podrá ser presentada por: – La persona presuntamente acosada (víctima) y/o por su representante legal. – La representación de las empleadas y empleados públicos en el ámbito en donde aquellos presten sus servicios. – Cualquier empleada y empleado público que tuviera conocimiento de situaciones que pudieran ser constitutivas de acoso sexual y/o de acoso por razón de sexo.\"</span>"},{"i":"16-164","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. ¿Cuál de los siguientes supuestos no es un supuesto de finalización del protocolo?","o":["Desistimiento de la víctima.","Cuando el acosador haya sido previamente sancionado por acoso sexual en el ámbito privado.","Archivo por falta de objeto o insuficiencia de indicios.","Imposición de sanción disciplinaria por la conducta constitutiva de acoso sexual o por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando el acosador haya sido previamente sancionado por acoso sexual en el ámbito privado.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), anexo II, apartado 4.2</span>. Entre los supuestos de archivo o finalización están el desistimiento de la víctima, el archivo por falta de objeto o insuficiencia de indicios y la sanción disciplinaria; que el acosador haya sido sancionado antes en el ámbito privado no lo es."},{"i":"16-187","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · I. Introducción. La igualdad entre mujeres y hombres es un principio jurídico universal reconocido por la normativa tanto internacional como española, y uno de los pilares fundamentales del:","o":["Estado social y democrático.","Estado de Derecho.","Ordenamiento constitucional.","Estado de Derecho y de los derechos humanos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Estado de Derecho</mark></span>El <span class=\"ref-norma\">apdo. I de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"y uno de los pilares fundamentales del Estado de Derecho\"</span>"},{"i":"16-189","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Dichos compromisos han de articularse expresamente por los departamentos ministeriales y los organismos públicos vinculados y dependientes de ellos, señalando y difundiendo los comportamientos que no serán tolerados y recordando que los mismos, de producirse, podrían ser calificados de:","o":["Falta grave.","Falta grave o muy grave.","Infracción muy grave en el orden social.","Falta muy grave."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Falta muy grave</mark></span>El <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"podrían ser calificados de falta muy grave\"</span>"},{"i":"16-ia-1134","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Real Decreto 247/2024: aplicación del Protocolo. De conformidad con la disposición final sexta de la Ley Orgánica 3/2007, la aplicación del protocolo tendrá lugar en el plazo de __________ desde la entrada en vigor del real decreto que lo aprueba.","o":["tres meses","un año","veinte días","seis meses"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">preámbulo de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"la aplicación del protocolo tendrá lugar en el plazo de seis meses desde la entrada en vigor de este real decreto\"</span>. La aplicación del protocolo tiene lugar en el plazo de seis meses desde la entrada en vigor del real decreto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1135","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Real Decreto 247/2024: negociación y aprobación del Protocolo. El Protocolo se negoció en la «Comisión Técnica para la igualdad de oportunidades y trato entre mujeres y hombres», dependiente de la Mesa General de Negociación de la Administración General del Estado, siendo aprobado por Acuerdo de __________ de dicha Mesa General.","o":["8 de marzo de 2024","28 de marzo de 2024, previo informe de la unidad policial competente.","28 de febrero de 2024","22 de marzo de 2024"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">28 de febrero de 2024</mark></span>El <span class=\"ref-norma\">preámbulo de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"siendo aprobado por Acuerdo de 28 de febrero de 2024 de dicha Mesa General\"</span>. El Acuerdo de la Mesa General es de 28 de febrero de 2024; el real decreto es de 8 de marzo y se publicó el 28 de marzo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1136","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Real Decreto 247/2024: aprobación. El real decreto se dicta a propuesta conjunta del Ministro para la Transformación Digital y de la Función Pública y de la Ministra de __________, y previa deliberación del Consejo de Ministros en su reunión del día 8 de marzo de 2024.","o":["la Presidencia, Justicia y Relaciones con las Cortes","Igualdad","Trabajo y Economía Social","Hacienda y Función Pública"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Igualdad</mark></span>El <span class=\"ref-norma\">preámbulo de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"a propuesta conjunta del Ministro para la Transformación Digital y de la Función Pública y de la Ministra de Igualdad\"</span>. La propuesta es conjunta del Ministro para la Transformación Digital y de la Función Pública y de la Ministra de Igualdad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1137","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Real Decreto 247/2024: régimen disciplinario. El Estatuto Básico del Empleado Público tipifica como falta muy grave toda actuación que suponga discriminación por razón de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual, lengua, opinión, lugar de nacimiento o vecindad, sexo o cualquier otra condición o circunstancia personal o social, así como el acoso por razón de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual y:","o":["el acoso moral.","el acoso sexual.","el acoso laboral.","el acoso por razón de sexo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el acoso moral</mark></span>El <span class=\"ref-norma\">preámbulo de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"así como el acoso por razón de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual y el acoso moral\"</span>. El texto del preámbulo cita el acoso por razón de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual y el acoso moral. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1140","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · I. Introducción. Queda expresamente prohibido cualquier comportamiento o conducta de acoso sexual o por razón de sexo, pudiendo ser considerada, con independencia de lo establecido en la legislación penal, como:","o":["falta grave, dando lugar a las sanciones que establece el Texto Refundido de la Ley del Estatuto Básico del Empleado Público, salvo que la autoridad judicial disponga otra cosa.","falta muy grave, dando lugar a las sanciones que establece el Texto Refundido de la Ley del Estatuto Básico del Empleado Público.","falta muy grave, dando lugar a las sanciones que establece la Ley de Infracciones y Sanciones en el Orden Social.","falta grave o muy grave, según las circunstancias, dando lugar a las sanciones del régimen disciplinario."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">falta muy grave, dando lugar a las sanciones que establece el Texto Refundido de la Ley del Estatuto Básico del Empleado Público</mark></span>En el <span class=\"ref-norma\">apdo. I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"pudiendo ser considerada, con independencia de lo establecido en la legislación penal, como falta muy grave\"</span>. Puede ser considerada falta muy grave, con las sanciones del Estatuto Básico del Empleado Público, con independencia de la legislación penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1204","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Señale la INCORRECTA sobre los objetivos específicos del protocolo:","o":["Fomentar la cultura preventiva del acoso sexual y/o por razón de sexo en todos los ámbitos y estamentos de la Administración General del Estado, en los términos que se determinen reglamentariamente.","Implantar un mecanismo sencillo, rápido, accesible y gratuito que permita a las víctimas de acoso realizar una notificación de la situación que está sufriendo.","Facilitar la identificación de las conductas constitutivas de acoso en sus distintas modalidades de acoso sexual y por razón de sexo.","Seguimiento de las actuaciones derivadas de la activación del protocolo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Implantar un mecanismo sencillo, rápido, accesible y gratuito que permita a las víctimas de acoso realizar una notificación de la situación que está sufriendo</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Implantar un mecanismo sencillo, rápido, accesible y confidencial que permita a las víctimas de acoso realizar una notificación de la situación que está sufriendo\"</span>. El mecanismo es sencillo, rápido, accesible y confidencial, no gratuito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1214","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.3 Garantías de actuación. La información recopilada en las actuaciones del protocolo tiene carácter confidencial y se respetará la normativa en materia de protección de datos. En particular, la Ley Orgánica __________, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales y el Reglamento (UE) 2016/679.","o":["15/1999","10/2022","3/2007","3/2018"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">3/2018</mark></span>En el <span class=\"ref-norma\">apdo. 2.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"En particular, la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales\"</span>. La norma citada es la LO 3/2018, de 5 de diciembre. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1237","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Dichos compromisos han de articularse expresamente por los departamentos ministeriales y los organismos públicos vinculados y dependientes de ellos, señalando y difundiendo los comportamientos que no serán tolerados y recordando que los mismos, de producirse, podrían ser calificados de:","o":["falta muy grave.","falta grave.","falta grave o muy grave.","infracción muy grave en el orden social."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">falta muy grave</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"de producirse, podrían ser calificados de falta muy grave\"</span>. Podrían ser calificados de falta muy grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1248","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. Entre las medidas de prevención figura la conveniencia de hacer un estudio de riesgos psicosociales, que permita conocer sobre una base científica cuáles son aquellos colectivos o grupos de personas trabajadoras más susceptibles de sufrir este tipo de acoso en cada centro de trabajo, informando de las conclusiones tanto al comité de seguridad y salud como a:","o":["la Mesa Delegada.","la comisión de igualdad.","la Dirección General de la Función Pública.","la Inspección de Trabajo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la comisión de igualdad</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"informando de las conclusiones tanto al comité de seguridad y salud como a la comisión de igualdad\"</span>. Las conclusiones se informan al comité de seguridad y salud y a la comisión de igualdad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1308","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Señale la INCORRECTA sobre quién puede presentar la comunicación de activación del protocolo:","o":["La persona presuntamente acosada (víctima) y/o su representante legal.","La persona presuntamente acosada, pero no su representante legal.","La representación de las empleadas y empleados públicos en el ámbito en donde aquellos presten sus servicios.","Cualquier empleada y empleado público que tuviera conocimiento de situaciones que pudieran ser constitutivas de acoso sexual y/o de acoso por razón de sexo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La persona presuntamente acosada, pero no su representante legal</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"La persona presuntamente acosada (víctima) y/o por su representante legal\"</span>. La comunicación puede presentarla la víctima y/o su representante legal, la representación del personal o cualquier empleado público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1312","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Durante el proceso de investigación las partes podrán estar acompañadas, si así lo solicitan __________, por una persona representante unitario o sindical u otra acompañante de su elección.","o":["por escrito","expresamente","ante la unidad receptora","motivadamente"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">expresamente</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"las partes podrán estar acompañadas, si así lo solicitan expresamente, por una persona representante unitario o sindical u otra acompañante de su elección\"</span>. El acompañamiento procede si así lo solicitan expresamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1344","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo II. Comité de Asesoramiento. Cuando el comité de asesoramiento lo estime necesario, podrá asistirle una persona experta en materia de igualdad y acoso sexual o por razón de sexo designada al efecto. Dicha persona deberá ser:","o":["asesor o asesora confidencial.","empleada o empleado público de la AGE.","representante de la organización sindical.","personal del Instituto de las Mujeres."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">empleada o empleado público de la AGE</mark></span>En el <span class=\"ref-norma\">Anexo II de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Dicha persona deberá ser empleada o empleado público de la AGE\"</span>. La persona experta debe ser empleada o empleado público de la AGE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1350","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo VI. Referencias normativas. Por otra parte, el acoso sexual está tipificado como sanción muy grave en el Real Decreto Legislativo __________, de 4 de agosto, por el que se aprueba el Texto refundido de la Ley sobre Infracciones y Sanciones en el Orden Social.","o":["5/2015, sin perjuicio de lo previsto en la normativa vigente.","2/2015","1/1995","5/2000"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">5/2000</mark></span>En el <span class=\"ref-norma\">Anexo VI de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"el acoso sexual está tipificado como sanción muy grave en el Real Decreto Legislativo 5/2000, de 4 de agosto\"</span>. Se trata del Real Decreto Legislativo 5/2000, de 4 de agosto (LISOS). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · Anexo I. Asesoría confidencial EX ✱","q":[{"i":"16-101","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Asesoría confidencial. Formación. ¿Quién diseñará los contenidos formativos del curso de «asesoría confidencial en la AGE»?","o":["La Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres.","El Instituto de las Mujeres, con la colaboración de la Dirección General de la Función Pública.","El Ministerio de Igualdad.","La Comisión Técnica de Igualdad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres</mark></span>El <span class=\"ref-norma\">Anexo I (apartado 4. Formación) del Real Decreto 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"La Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres y, en su caso de personas expertas, diseñará los contenidos formativos del curso de «asesoría confidencial en la AGE».\"</span>"},{"i":"16-191","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. Entre los principios de actuación del asesor o asesora confidencial se encuentra:","o":["La proporcionalidad.","La neutralidad.","La mínima intervención.","La oportunidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La neutralidad</mark></span>El <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Neutralidad. – Presunción de inocencia\"</span>"},{"i":"16-192","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. Entre los principios de actuación del asesor o asesora confidencial se encuentra:","o":["La presunción de veracidad, en los términos que determine la ley orgánica correspondiente.","La proporcionalidad.","La presunción de inocencia.","La celeridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La presunción de inocencia</mark></span>El <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Neutralidad. – Presunción de inocencia\"</span>"},{"i":"16-ia-1337","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. Cualquier empleada y empleado público voluntariamente, tras recibir la formación necesaria, podrá ser designado asesor o asesora confidencial por:","o":["la persona titular de la unidad responsable de la recepción de la comunicación o solicitud de activación del protocolo.","la persona titular de la jefatura superior de personal del departamento ministerial u organismo público, salvo que la autoridad judicial disponga otra cosa.","la Dirección General de la Función Pública.","la comisión de igualdad dependiente de la Mesa Delegada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la persona titular de la unidad responsable de la recepción de la comunicación o solicitud de activación del protocolo</mark></span>En el <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"podrá ser designada por la persona titular de la unidad responsable de la recepción de la comunicación o solicitud de activación del protocolo\"</span>. La designación corresponde a la persona titular de la unidad responsable de la recepción de la comunicación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1338","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. En la confección del listado de asesoras y asesores confidenciales, la unidad responsable procurará que la lista esté integrada por personas que ostenten distintas categorías profesionales, que pertenezcan a __________ y que sean adecuados en número.","o":["distintos departamentos","distintas organizaciones sindicales","distintas localidades","ambos sexos"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ambos sexos</mark></span>En el <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que pertenezcan a ambos sexos y que sean adecuados en número\"</span>. La lista procura incluir distintas categorías profesionales, ambos sexos y un número adecuado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1340","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. Para el desempeño de las funciones de asesoría confidencial será necesario haber superado el curso de asesoría confidencial en la AGE o una formación equivalente. El módulo no será inferior a __________ de contenido eminentemente práctico.","o":["50 horas","100 horas","150 horas, previo informe de la unidad policial competente.","200 horas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">100 horas</mark></span>En el <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El módulo, que no será inferior a 100 horas de contenido eminentemente práctico\"</span>. El módulo no será inferior a 100 horas de contenido eminentemente práctico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1341","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo I. Asesoría confidencial. Los contenidos formativos del curso de asesoría confidencial en la AGE los diseñará:","o":["la Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres y, en su caso, de personas expertas.","el Instituto de las Mujeres, con la colaboración de la Dirección General de la Función Pública y, en su caso, de personas expertas.","el Ministerio de Igualdad, con la colaboración de las organizaciones sindicales.","el Instituto Nacional de Administración Pública, con la colaboración del Instituto de las Mujeres."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres y, en su caso, de personas expertas</mark></span>En el <span class=\"ref-norma\">Anexo I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"La Dirección General de la Función Pública, con la colaboración del Instituto de las Mujeres y, en su caso de personas expertas, diseñará los contenidos formativos del curso\"</span>. La Dirección General de la Función Pública los diseña, con la colaboración del Instituto de las Mujeres y, en su caso, de personas expertas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · I. Introducción EXOF","q":[{"i":"16-115","p":"Texto: Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. ¿Quién define la «violencia contra las mujeres» como una violación de los derechos humanos y una forma de discriminación contra las mujeres, que designará todos los actos de violencia basados en el género que implican o pueden implicar para las mujeres daños o sufrimientos de naturaleza física, sexual, psicológica o económica, incluidas las amenazas de realizar dichos actos, la coacción o la privación arbitraria de libertad, en la vida pública o privada?","o":["El Consejo del Poder Judicial.","La Organización Internacional del Trabajo.","El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica, hecho en Estambul en 2011.","La Organización de las Naciones Unidas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica, hecho en Estambul en 2011</mark></span>El <span class=\"ref-norma\">apartado I (Introducción) del Real Decreto 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"El convenio define la «violencia contra las mujeres» como una violación de los derechos humanos y una forma de discriminación contra las mujeres, que designará todos los actos de violencia basados en el género que implican o pueden implicar para las mujeres daños o sufrimientos de naturaleza física, sexual, psicológica o económica, incluidas las amenazas de realizar dichos actos, la coacción o la privación arbitraria de libertad, en la vida pública o privada.\"</span>"},{"i":"16-137","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. La definición \"la violencia contra las mujeres no es el resultado de actos aleatorios e individuales de mala conducta, sino que está profundamente arraigada en las relaciones estructurales del poder que ejercen los hombres contra las mujeres\" la elabora:","o":["Las Naciones Unidas.","El Consejo de Europa.","El Parlamento Europeo.","La Organización Internacional del Trabajo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Naciones Unidas</mark></span>El <span class=\"ref-norma\">apartado I (Introducción) del Real Decreto 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"De acuerdo con las Naciones Unidas, la violencia contra las mujeres no es el resultado de actos aleatorios e individuales de mala conducta, sino que está profundamente arraigada en las relaciones estructurales del poder que ejercen los hombres contra las mujeres.\"</span>"},{"i":"16-153","p":"Real Decreto 247/2024. La definición \"la violencia contra las mujeres no es el resultado de actos aleatorios e individuales de mala conducta, sino que está profundamente arraigada en las relaciones estructurales del poder que ejercen los hombres contra las mujeres\" la elabora:","o":["Las Naciones Unidas.","El Consejo de Europa.","El Parlamento Europeo.","La Organización Internacional del Trabajo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Naciones Unidas</mark></span>El <span class=\"ref-norma\">apartado I (Introducción) del Real Decreto 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"De acuerdo con las Naciones Unidas, la violencia contra las mujeres no es el resultado de actos aleatorios e individuales de mala conducta, sino que está profundamente arraigada en las relaciones estructurales del poder que ejercen los hombres contra las mujeres.\"</span>"},{"i":"16-165","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Los órganos y personal directivo de la Administración General del Estado deben proveer todos los medios a su alcance para prevenir, sensibilizar, evitar y, en su caso, detectar y eliminar cualquier situación de acoso sexual o de acoso por razón de sexo, así como sancionar cualquier conducta que lleve a tales situaciones, garantizando en todo caso, que la asistencia y protección de las víctimas se realice siguiendo los: señale la INCORRECTA.","o":["Principio de sigilo.","Principio de mínima intervención.","Principio de respeto.","Principio de objetividad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Principio de mínima intervención.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), anexo I, apartado 2.1.2 (principios de actuación)</span>. Los principios incluyen respeto y protección, diligencia, celeridad, imparcialidad, audiencia, confidencialidad y sigilo, objetividad y no revictimización; la «mínima intervención» no figura."},{"i":"16-ia-1138","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · I. Introducción. El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica, hecho en Estambul en 2011, fue ratificado por España en:","o":["2011, sin perjuicio de lo previsto en la normativa vigente.","2012.","2016.","2014."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">2014</mark></span>En el <span class=\"ref-norma\">apdo. I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"hecho en Estambul en 2011, ratificado por España en 2014\"</span>. El Convenio de Estambul se hizo en 2011 y fue ratificado por España en 2014. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1139","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · I. Introducción. El presente protocolo tiene por finalidad definir, __________ y comunicar a todo el personal a su servicio las medidas que la Administración General del Estado despliega para evitar los casos de acoso sexual y acoso por razón de sexo.","o":["desarrollar, en los términos que se determinen reglamentariamente.","aprobar","implementar","difundir"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">implementar</mark></span>En el <span class=\"ref-norma\">apdo. I de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"tiene por finalidad definir, implementar y comunicar a todo el personal a su servicio las medidas\"</span>. La finalidad es definir, implementar y comunicar las medidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1327","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.5 Información. En cualquier caso, se hará una revisión de la situación __________ en que ha quedado finalmente la persona que ha presentado la solicitud de activación.","o":["personal","profesional","laboral","administrativa"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">laboral</mark></span>En el <span class=\"ref-norma\">apdo. 4.5 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se hará una revisión de la situación laboral en que ha quedado finalmente la persona que ha presentado la solicitud de activación\"</span>. Se revisa la situación laboral de quien presentó la solicitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · Anexo VI. Referencias normativas","q":[{"i":"16-159","p":"Ley Orgánica 3/2007, para la Igualdad Efectiva de Mujeres y Hombres. Las Administraciones públicas, en el ámbito de sus respectivas competencias y en aplicación del principio de igualdad entre hombres y mujeres, deberán: señale la INCORRECTA.","o":["Remover los obstáculos que impidan o la pervivencia de cualquier tipo de discriminación.","Facilitar la conciliación de la vida personal, familiar y laboral, menoscabando incluso la promoción profesional.","Fomentar la formación en igualdad.","Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Facilitar la conciliación de la vida personal, familiar y laboral, menoscabando incluso la promoción profesional.</mark></span><span class=\"ref-norma\">Ley Orgánica 3/2007, art. 51 (criterios de actuación de las Administraciones públicas)</span>. Las Administraciones deben facilitar la conciliación de la vida personal, familiar y laboral sin menoscabo de la promoción profesional; la opción B dice lo contrario («menoscabando»), y por eso es la incorrecta."},{"i":"16-ia-1349","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo VI. Referencias normativas. Entre las referencias normativas internacionales del protocolo figura el Convenio 190 de la OIT sobre:","o":["la eliminación de la violencia y el acoso en el mundo del trabajo.","la discriminación en materia de empleo y ocupación.","la igualdad de remuneración entre la mano de obra masculina y la femenina.","la protección de la maternidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la eliminación de la violencia y el acoso en el mundo del trabajo</mark></span>En el <span class=\"ref-norma\">Anexo VI de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Convenio 190 de la OIT sobre la eliminación de la violencia y el acoso en el mundo del trabajo\"</span>. El Convenio 190 trata de la eliminación de la violencia y el acoso en el mundo del trabajo; el 111, de la discriminación (empleo y ocupación). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · IV. Procedimiento · 4.4 Constitución del Comité de Asesoramiento","q":[{"i":"16-162","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. En el caso de que la víctima esté en desacuerdo con las conclusiones, dispondrá de un plazo de ___ para presentar alegaciones a la unidad receptora y solicitar la intervención del comité de asesoramiento designado al efecto.","o":["siete días.","diez días.","quince días.","veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">diez días.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), anexo II, apartado 4.4</span>. Si la víctima no está de acuerdo con las conclusiones, dispone de diez días para presentar alegaciones."},{"i":"16-ia-1321","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.4 Constitución del Comité de Asesoramiento. En el caso de que la víctima esté en desacuerdo con las conclusiones, dispondrá de un plazo de __________ para presentar alegaciones a la unidad receptora y solicitar la intervención del comité de asesoramiento designado al efecto.","o":["diez días","cinco días","siete días","veinte días"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días</mark></span>En el <span class=\"ref-norma\">apdo. 4.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"dispondrá en un plazo de diez días para presentar alegaciones a la unidad receptora y solicitar la intervención del comité de asesoramiento\"</span>. El plazo de alegaciones de la víctima es de diez días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1323","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.4 Constitución del Comité de Asesoramiento. La remisión de alegaciones motivará que la unidad receptora constituya el comité de asesoramiento en el plazo de __________, manteniéndose las medidas organizativas que se hubieran establecido.","o":["diez días","cinco días","siete días","veinticuatro horas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">siete días</mark></span>En el <span class=\"ref-norma\">apdo. 4.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"constituya el comité de asesoramiento en el plazo de siete días\"</span>. El comité se constituye en el plazo de siete días y se mantienen las medidas organizativas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1325","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.4 Constitución del Comité de Asesoramiento. El plazo de la etapa de la asesoría confidencial no será superior a diez días, mientras que el plazo de la etapa del comité de asesoramiento, una vez constituido, no será superior a:","o":["veinte días.","diez días.","quince días.","treinta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">veinte días</mark></span>En el <span class=\"ref-norma\">apdo. 4.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El plazo de esta etapa una vez constituido el comité no será superior a veinte días, salvo excepciones justificadas\"</span>. Una vez constituido el comité, su etapa no es superior a veinte días, salvo excepciones justificadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · II. Política de prevención · 2.1 Principios rectores","q":[{"i":"16-163","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. ¿Cuál de los siguientes no es un principio de actuación en la fase de investigación del protocolo?","o":["Sigilo.","No revictimización.","Presunción de inocencia.","Arbitraje."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Arbitraje.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), principios de actuación</span>. Entre los principios están el sigilo, la no revictimización y la presunción de inocencia; el arbitraje no es un principio ni una fase del procedimiento."},{"i":"16-ia-1141","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. El protocolo resulta de aplicación a todo el personal de la Administración General del Estado independientemente del departamento ministerial u organismo público donde preste sus servicios o de la categoría profesional, incluyendo las personas en formación, las que realizan prácticas __________, etc.","o":["no laborales","laborales","docentes","profesionales"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no laborales</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"incluyendo las personas en formación, las que realizan prácticas no laborales, etc\"</span>. Se incluye a las personas que realizan prácticas no laborales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1142","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. La persona afectada por un comportamiento susceptible de ser constitutivo de acoso sexual o acoso por razón de sexo (víctima), incluyendo el realizado a través de medios tecnológicos, informáticos o ciberacoso, podrá solicitar la activación del protocolo y tendrá derecho a obtener una respuesta, debiendo siempre la Administración dejar constancia por escrito, incluso cuando los hechos sean comunicados:","o":["por terceros, así como de todo lo actuado en aplicación de este protocolo.","de forma anónima, así como de las medidas organizativas adoptadas.","ante la representación sindical, así como del informe final de conclusiones.","verbalmente, así como de todo lo actuado en aplicación de este protocolo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">verbalmente, así como de todo lo actuado en aplicación de este protocolo</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"debiendo siempre la Administración dejar constancia por escrito, incluso cuando los hechos sean comunicados verbalmente, así como de todo lo actuado en aplicación de este protocolo\"</span>. La Administración deja constancia por escrito incluso de lo comunicado verbalmente y de todo lo actuado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1144","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. La obligación de poner en conocimiento los casos de posible acoso debe ir acompañada del establecimiento de un mecanismo sencillo, __________ y accesible de la comunicación, garantizando la confidencialidad.","o":["ágil","rápido","gratuito","seguro"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">rápido</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"un mecanismo sencillo, rápido y accesible de la comunicación, garantizando la confidencialidad\"</span>. El mecanismo debe ser sencillo, rápido y accesible, garantizando la confidencialidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1145","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. Entre los principios que debe comprender el protocolo según la Ley Orgánica 3/2007 figura el tratamiento reservado de la __________ de los hechos que pudieran ser constitutivos de acoso sexual o de acoso por razón de sexo, sin perjuicio de lo establecido en la normativa de régimen disciplinario.","o":["comunicación","denuncia","investigación","tramitación"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">comunicación</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El tratamiento reservado de la comunicación de los hechos que pudieran ser constitutivos de acoso sexual o de acoso por razón de sexo\"</span>. El Protocolo reproduce el principio hablando del tratamiento reservado de la comunicación de los hechos (la Ley habla de las denuncias de hechos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1146","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. Se establecerán las medidas necesarias para la completa recuperación de las víctimas y las garantías de no repetición, así como acciones de reparación:","o":["económica y simbólica.","material y moral.","integral y simbólica.","material y simbólica."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">material y simbólica</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"así como acciones de reparación material y simbólica\"</span>. Las acciones de reparación son materiales y simbólicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1147","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. El Protocolo cumple con lo dispuesto en la Ley Orgánica __________, de 6 de septiembre, de garantía integral de la libertad sexual (LOGILS), que establece la obligación de las Administraciones Públicas de arbitrar procedimientos o protocolos específicos para la prevención, detección temprana, denuncia y asesoramiento a quienes hayan sido víctimas de estas conductas.","o":["10/1995, previo informe de la unidad policial competente.","3/2018","10/2022","1/2004"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">10/2022</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"el protocolo cumple con lo dispuesto en el artículo 13.1 de Ley Orgánica 10/2022, de 6 de septiembre, de garantía integral de la libertad sexual\"</span>. La norma citada es la LO 10/2022, de 6 de septiembre, de garantía integral de la libertad sexual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1148","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.1 Principios rectores. Las medidas aplicadas en ejecución del presente protocolo se mantendrán efectivas salvo que en el ámbito __________ se decida su suspensión o la adopción de otras medidas.","o":["disciplinario o judicial, sin perjuicio de lo previsto en la normativa vigente.","administrativo o judicial","administrativo o laboral","judicial exclusivamente"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">administrativo o judicial</mark></span>En el <span class=\"ref-norma\">apdo. 2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se mantendrán efectivas salvo que en el ámbito administrativo o judicial se decida su suspensión o la adopción de otras medidas\"</span>. Solo se suspenden o sustituyen si en el ámbito administrativo o judicial así se decide. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · IV. Procedimiento · 4.3 Conclusiones e informe","q":[{"i":"16-167","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Conclusiones e informe. Al finalizar la investigación, la asesoría confidencial emitirá un informe de valoración, con las conclusiones y propuestas que se deriven de la misma. Salvo excepciones justificadas, el plazo de esta etapa no será superior a:","o":["Cinco días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días.</mark></span>El <span class=\"ref-norma\">apdo. 4.3 del Protocolo (RD 247/2024)</span> dispone: <span class=\"ref-concepto\">\"El plazo de esta etapa no será superior a diez días, salvo excepciones justificadas.\"</span> Los veinte días son el plazo de la etapa del comité de asesoramiento, una vez constituido."},{"i":"16-ia-1314","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.3 Conclusiones e informe. Al finalizar la investigación, quien emitirá un informe de valoración, con las conclusiones y propuestas que se deriven de la misma, es:","o":["la unidad receptora.","el comité de asesoramiento.","la jefatura superior de personal.","la asesoría confidencial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la asesoría confidencial</mark></span>En el <span class=\"ref-norma\">apdo. 4.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Al finalizar la investigación, la asesoría confidencial emitirá un informe de valoración, con las conclusiones y propuestas que se deriven de la misma\"</span>. El informe de valoración lo emite la asesoría confidencial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1316","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.3 Conclusiones e informe. Cuando se hayan realizado entrevistas a testigos, y con el fin de garantizar la confidencialidad, el resumen de esta actuación en el informe no ha de indicar quién hace la manifestación, sino solo:","o":["el contenido literal de lo manifestado.","si se constata o no la realidad de los hechos investigados.","el departamento al que pertenece el testigo, previo informe de la unidad policial competente.","si el testigo ratifica su declaración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">si se constata o no la realidad de los hechos investigados</mark></span>En el <span class=\"ref-norma\">apdo. 4.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"no ha de indicar quién hace la manifestación, sino solo si se constata o no la realidad de los hechos investigados\"</span>. Solo se indica si se constata o no la realidad de los hechos investigados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1318","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.3 Conclusiones e informe. En caso de desistimiento de la víctima, la comunicación se archiva, sin perjuicio de que:","o":["se continúe la investigación si lo solicita la representación sindical, salvo que la autoridad judicial disponga otra cosa.","se proponga el inicio de expediente disciplinario por falta grave.","se mantengan las medidas organizativas durante seis meses.","se continúe, de oficio, la investigación si se detectasen indicios de acoso sexual o por razón de sexo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se continúe, de oficio, la investigación si se detectasen indicios de acoso sexual o por razón de sexo</mark></span>En el <span class=\"ref-norma\">apdo. 4.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Desistimiento de la víctima, sin perjuicio de que se continúe, de oficio, la investigación si se detectasen indicios de acoso sexual o por razón de sexo\"</span>. Tras el desistimiento se continúa de oficio si se detectasen indicios de acoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1319","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.3 Conclusiones e informe. En la primera etapa del procedimiento, el plazo para la emisión del informe de valoración no será superior a __________, salvo excepciones justificadas.","o":["veinte días","siete días","diez días","un mes"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">diez días</mark></span>En el <span class=\"ref-norma\">apdo. 4.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El plazo de esta etapa no será superior a diez días, salvo excepciones justificadas\"</span>. El plazo de esta etapa no es superior a diez días, salvo excepciones justificadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1320","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.3 Conclusiones e informe. El informe de valoración se remitirá a la unidad receptora para dar conocimiento a las partes, que son:","o":["la víctima, la presunta persona acosadora y la representación sindical.","la víctima, la presunta persona acosadora y la jefatura superior de personal del departamento ministerial u organismo público.","la víctima y la jefatura superior de personal, pero no la presunta persona acosadora.","la víctima, la presunta persona acosadora y el órgano competente para incoar el expediente, previo informe de la unidad policial competente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la víctima, la presunta persona acosadora y la jefatura superior de personal del departamento ministerial u organismo público</mark></span>En el <span class=\"ref-norma\">apdo. 4.3 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El informe se remitirá a la unidad receptora para dar conocimiento a las partes (víctima, presunta persona acosadora y a la jefatura superior de personal del departamento ministerial u organismo público)\"</span>. Las partes son la víctima, la presunta persona acosadora y la jefatura superior de personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo ✱","q":[{"i":"16-168","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. ¿Cómo se denomina al tipo de acoso sexual donde la persona acosadora crea un entorno intimidatorio, hostil, degradante, humillante u ofensivo para la víctima, como consecuencia de actitudes y comportamientos indeseados de naturaleza sexual?:","o":["Acoso sexual ambiental.","Acoso sexual espacial.","Acoso sexual específico del lugar.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Acoso sexual ambiental.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), definición de acoso sexual</span> dispone: <span class=\"ref-concepto\">\"entorno intimidatorio, hostil, degradante, humillante u ofensivo\"</span>. Ese entorno es lo que la doctrina y el ámbito laboral llaman acoso sexual ambiental."},{"i":"16-194","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo. Entre las conductas no verbales constitutivas de acoso sexual del listado no exhaustivo del protocolo figuran las cartas o mensajes de correo electrónico o en redes sociales de carácter:","o":["Ofensivo y con claro contenido sexual.","Ofensivo o con contenido sexual implícito.","Reiterado y con contenido sexual.","Intimidatorio y con claro contenido sexual."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ofensivo y con claro contenido sexual</mark></span>El <span class=\"ref-norma\">Anexo V de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Cartas o mensajes de correo electrónico o en redes sociales de carácter ofensivo y con claro contenido sexual\"</span>"},{"i":"16-195","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo. Entre los comportamientos físicos constitutivos de acoso sexual del listado no exhaustivo del protocolo figura el contacto físico:","o":["Reiterado y no consentido.","Deliberado y no solicitado.","Deliberado e intimidatorio, salvo que el órgano competente acuerde otra cosa de forma motivada.","Excesivo y no solicitado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Deliberado y no solicitado</mark></span>El <span class=\"ref-norma\">Anexo V de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Contacto físico deliberado y no solicitado\"</span>"},{"i":"16-ia-1346","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo. En el chantaje sexual (acoso sexual quid pro quo), en la medida que supone un abuso de autoridad, la persona acosadora será aquella que tenga poder, sea directa o indirectamente, para:","o":["imponer sanciones disciplinarias a la víctima.","decidir sobre la promoción y la retribución de la víctima, salvo que la autoridad judicial disponga otra cosa.","ordenar su traslado a otro puesto de trabajo.","proporcionar o retirar un beneficio o condición de trabajo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">proporcionar o retirar un beneficio o condición de trabajo</mark></span>En el <span class=\"ref-norma\">Anexo V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"la persona acosadora será aquella que tenga poder, sea directa o indirectamente, para proporcionar o retirar un beneficio o condición de trabajo\"</span>. Quien acosa tiene poder, directa o indirectamente, para proporcionar o retirar un beneficio o condición de trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1347","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo. En el acoso sexual ambiental la persona acosadora crea un entorno intimidatorio, hostil, degradante, humillante u ofensivo para la víctima, como consecuencia de actitudes y comportamientos indeseados de naturaleza sexual. Pueden ser realizados por:","o":["cualquier miembro de la empresa que ocupe una posición jerárquica superior a la víctima.","cualquier persona con poder para proporcionar o retirar un beneficio o condición de trabajo.","cualquier miembro de la empresa, con independencia de su posición o estatus, o por terceras personas ubicadas de algún modo en el entorno de trabajo.","cualquier miembro de la empresa, con exclusión de terceras personas ubicadas en el entorno de trabajo, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cualquier miembro de la empresa, con independencia de su posición o estatus, o por terceras personas ubicadas de algún modo en el entorno de trabajo</mark></span>En el <span class=\"ref-norma\">Anexo V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Pueden ser realizados por cualquier miembro de la empresa, con independencia de su posición o estatus, o por terceras personas ubicadas de algún modo en el entorno de trabajo\"</span>. Puede realizarlo cualquier miembro de la empresa o terceras personas ubicadas en el entorno de trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1348","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo V. Situaciones de acoso sexual y por razón de sexo. Señale cuál NO figura entre las conductas constitutivas de acoso por razón de sexo del listado no exhaustivo del protocolo:","o":["Demérito de la valía profesional por el hecho de la maternidad o paternidad.","Abrazos o besos no deseados.","Asignar tareas sin sentido o imposibles de lograr (plazos irracionales) a una persona en función de su sexo.","Ignorar aportaciones, comentarios o acciones (excluir, no tomar en serio)."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Abrazos o besos no deseados</mark></span>En el <span class=\"ref-norma\">Anexo V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Demérito de la valía profesional por el hecho de la maternidad o paternidad\"</span>. Los abrazos o besos no deseados son un comportamiento físico constitutivo de acoso sexual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · 2.5 Compromisos · 2.5.2 Compromisos de la representación sindical de las empleadas y empleados públicos","q":[{"i":"16-172","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. En todo caso, la representación de las organizaciones sindicales tendrá el deber de ___ respecto de aquellos hechos que pudieran tener conocimiento en el ejercicio de su representación.","o":["respeto.","sigilo.","confidencialidad.","objetividad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sigilo.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), anexo II, apartado 1.4</span>. La representación sindical tiene el deber de sigilo respecto de los hechos que conozca."},{"i":"16-ia-1240","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. La representación sindical de la correspondiente comisión de igualdad departamental tendrá derecho a recibir información periódica sobre:","o":["las personas implicadas en cada activación del protocolo, los resultados de las investigaciones y las medidas que se adopten, previo informe de la unidad policial competente.","el número de veces que se ha activado el protocolo, los resultados de las investigaciones, incluyendo el archivo de las actuaciones, y las medidas que se adopten.","el número de veces que se ha activado el protocolo y el contenido de los informes de valoración de la asesoría confidencial.","el número de comunicaciones recibidas, con identificación de las partes, y las medidas organizativas adoptadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el número de veces que se ha activado el protocolo, los resultados de las investigaciones, incluyendo el archivo de las actuaciones, y las medidas que se adopten</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"información periódica sobre el número de veces que se ha activado el protocolo de acoso sexual y acoso por razón de sexo, de los resultados de las investigaciones, incluyendo el archivo de las actuaciones, las medidas que se adopten\"</span>. La información no puede contener datos de carácter personal de las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1241","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. En todo caso, la representación de las organizaciones sindicales tendrá el deber de __________ respecto de aquellos hechos de los que pudieran tener conocimiento en el ejercicio de su representación.","o":["sigilo","confidencialidad","reserva","colaboración"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">sigilo</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"tendrá el deber de sigilo respecto de aquellos hechos de los que pudieran tener conocimiento en el ejercicio de su representación\"</span>. La representación sindical tiene el deber de sigilo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1242","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Asimismo, la representación sindical de la comisión de igualdad departamental será informada del número de:","o":["expedientes disciplinarios y sentencias dictadas como consecuencia de un acoso sexual o por razón de sexo, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","sanciones impuestas y recursos presentados como consecuencia de la activación del protocolo.","bajas laborales y traslados motivados por la activación del protocolo.","expedientes disciplinarios y acciones judiciales del que se tenga conocimiento como consecuencia de un acoso sexual o por razón de sexo o motivados por la activación del protocolo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">expedientes disciplinarios y acciones judiciales del que se tenga conocimiento como consecuencia de un acoso sexual o por razón de sexo o motivados por la activación del protocolo</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se informará del número de expedientes disciplinarios y acciones judiciales del que se tenga conocimiento como consecuencia de un acoso sexual o por razón de sexo o motivados por la activación del protocolo\"</span>. Se informa del número de expedientes disciplinarios y acciones judiciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 62 — Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo ✱","q":[{"i":"16-177","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Para la prevención del acoso sexual y el acoso por razón de sexo, las Administraciones Públicas negociarán con la representación legal de las trabajadoras y trabajadores, un protocolo de actuación que comprenderá, al menos, los siguientes principios: señale la CORRECTA.","o":["La instrucción a todo el personal de su derecho de respetar la dignidad de la víctima.","El incumplimiento público de la comunicación de los hechos que pudieran ser constitutivos de acoso sexual o de acoso por razón de sexo, sin perjuicio de lo establecido en la normativa de régimen disciplinario.","La identificación de las personas responsables de atender a quienes formulen una queja o denuncia.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La identificación de las personas responsables de atender a quienes formulen una queja o denuncia.</mark></span><span class=\"ref-norma\">Real Decreto 247/2024 (Protocolo frente al acoso sexual y por razón de sexo), anexo I, apartado 2.1.3.c</span>. Es una medida preventiva obligatoria: la identificación de las personas responsables de atender a quienes formulen una queja o denuncia."},{"i":"16-186","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo. Entre los principios que, al menos, debe comprender el protocolo de actuación frente al acoso sexual y al acoso por razón de sexo figura la instrucción a todo el personal de su deber de respetar:","o":["La dignidad de las personas y su derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres.","La dignidad de las personas y su derecho a la intimidad, así como el deber de denunciar los hechos de acoso.","La intimidad de las personas y su derecho a la igualdad de trato, así como la confidencialidad de las denuncias.","La dignidad y el honor de las personas, así como la igualdad de trato entre mujeres y hombres."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La dignidad de las personas y su derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres</mark></span>El <span class=\"ref-norma\">art. 62.b de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"La instrucción a todo el personal de su deber de respetar la dignidad de las personas y su derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres\"</span>"},{"i":"16-ia-1121","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo. Para la prevención del acoso sexual y del acoso por razón de sexo, las Administraciones públicas __________ con la representación legal de las trabajadoras y trabajadores, un protocolo de actuación que comprenderá, al menos, los siguientes principios.","o":["negociarán","aprobarán","pactarán","consultarán"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">negociarán</mark></span>El <span class=\"ref-norma\">art. 62 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"las Administraciones públicas negociarán con la representación legal de las trabajadoras y trabajadores, un protocolo de actuación\"</span>. Las Administraciones públicas negocian el protocolo con la representación legal del personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1122","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo. El protocolo de actuación frente al acoso sexual y al acoso por razón de sexo comprenderá, al menos, el tratamiento __________ de las denuncias de hechos que pudieran ser constitutivos de acoso sexual o de acoso por razón de sexo, sin perjuicio de lo establecido en la normativa de régimen disciplinario.","o":["confidencial","anónimo","urgente","reservado"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">reservado</mark></span>El <span class=\"ref-norma\">art. 62.c de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"El tratamiento reservado de las denuncias de hechos que pudieran ser constitutivos de acoso sexual o de acoso por razón de sexo\"</span>. El principio es el tratamiento reservado de las denuncias, sin perjuicio del régimen disciplinario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1123","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo. Señale la INCORRECTA sobre los principios que, al menos, debe comprender el protocolo de actuación frente al acoso sexual y al acoso por razón de sexo:","o":["El compromiso de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella de prevenir y no tolerar el acoso sexual y el acoso por razón de sexo.","La instrucción a todo el personal de su deber de respetar la dignidad de las personas y su derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres.","La instrucción a todo el personal de su deber de denunciar ante la Inspección de Trabajo los hechos de acoso de los que tenga conocimiento.","La identificación de las personas responsables de atender a quienes formulen una queja o denuncia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La instrucción a todo el personal de su deber de denunciar ante la Inspección de Trabajo los hechos de acoso de los que tenga conocimiento</mark></span>El <span class=\"ref-norma\">art. 62 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"La instrucción a todo el personal de su deber de respetar la dignidad de las personas y su derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres\"</span>. La instrucción al personal se refiere a respetar la dignidad, la intimidad y la igualdad de trato; no a denunciar ante la Inspección de Trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 54 — Designación de representantes de la Administración General del Estado ✱","q":[{"i":"16-183","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Designación de representantes de la Administración General del Estado. La Administración General del Estado y los organismos públicos vinculados o dependientes de ella designarán a sus representantes en órganos colegiados, comités de personas expertas o comités consultivos, nacionales o internacionales, de acuerdo con el principio de presencia equilibrada de mujeres y hombres, salvo por razones:","o":["Fundadas y excepcionales, debidamente justificadas.","Fundadas y objetivas, debidamente motivadas.","Objetivas y urgentes, debidamente motivadas.","Organizativas y objetivas, debidamente acreditadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Fundadas y objetivas, debidamente motivadas</mark></span>El <span class=\"ref-norma\">art. 54 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"de acuerdo con el principio de presencia equilibrada de mujeres y hombres, salvo por razones fundadas y objetivas, debidamente motivadas\"</span>"},{"i":"16-184","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Designación de representantes de la Administración General del Estado. La Administración General del Estado y los organismos públicos vinculados o dependientes de ella observarán el principio de presencia equilibrada en los nombramientos que le corresponda efectuar en los consejos de administración de las empresas:","o":["En cuyo capital participe de forma mayoritaria.","Públicas que dependan de ella.","En cuyo capital participe.","Con las que haya suscrito contratos de colaboración."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En cuyo capital participe</mark></span>El <span class=\"ref-norma\">art. 54 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"en los nombramientos que le corresponda efectuar en los consejos de administración de las empresas en cuyo capital participe\"</span>"},{"i":"16-ia-1108","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Designación de representantes de la Administración General del Estado. La Administración General del Estado y los organismos públicos vinculados o dependientes de ella designarán a sus representantes en órganos colegiados, comités de personas expertas o comités __________, nacionales o internacionales, de acuerdo con el principio de presencia equilibrada de mujeres y hombres, salvo por razones fundadas y objetivas, debidamente motivadas.","o":["asesores","consultivos","técnicos","científicos, salvo que la autoridad judicial disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">consultivos</mark></span>El <span class=\"ref-norma\">art. 54 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"comités de personas expertas o comités consultivos, nacionales o internacionales\"</span>. Son órganos colegiados, comités de personas expertas o comités consultivos, nacionales o internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1109","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Designación de representantes de la Administración General del Estado. La Administración General del Estado y los organismos públicos vinculados o dependientes de ella observarán el principio de presencia equilibrada en los nombramientos que le corresponda efectuar en los consejos de administración de las empresas:","o":["en cuyo capital participe.","en cuyo capital participe de forma mayoritaria.","públicas dependientes de ella.","con las que haya suscrito contratos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en cuyo capital participe</mark></span>El <span class=\"ref-norma\">art. 54 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"en los nombramientos que le corresponda efectuar en los consejos de administración de las empresas en cuyo capital participe\"</span>. Se refiere a las empresas en cuyo capital participe, no solo a las de participación mayoritaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 — Formación para la igualdad ✱","q":[{"i":"16-185","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Formación para la igualdad. Todas las pruebas de acceso al empleo público de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella contemplarán:","o":["El estudio de la normativa sobre igualdad de trato y prevención de la violencia de género.","La aplicación del principio de igualdad, pero no su estudio, en los diversos ámbitos de la función pública, sin perjuicio de lo que establezcan los tratados internacionales.","Una prueba específica sobre igualdad de trato y de oportunidades entre mujeres y hombres.","El estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública</mark></span>El <span class=\"ref-norma\">art. 61.1 de la LO 3/2007</span> dispone: <span class=\"ref-concepto\">\"contemplarán el estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública\"</span>"},{"i":"16-ia-1119","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Formación para la igualdad. Todas las pruebas de acceso al empleo público de la Administración General del Estado y de los organismos públicos vinculados o dependientes de ella contemplarán:","o":["el estudio de la normativa sobre igualdad de trato y sobre prevención de la violencia de género.","la aplicación del principio de igualdad entre mujeres y hombres, pero no su estudio, en los diversos ámbitos de la función pública.","el estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública.","una prueba específica sobre igualdad de trato y oportunidades entre mujeres y hombres."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública</mark></span>El <span class=\"ref-norma\">art. 61.1 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"contemplarán el estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública\"</span>. Las pruebas contemplarán el estudio y la aplicación del principio de igualdad entre mujeres y hombres en los diversos ámbitos de la función pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1120","p":"Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres. Formación para la igualdad. La Administración General del Estado y los organismos públicos vinculados o dependientes de ella impartirán cursos de formación sobre la igualdad de trato y oportunidades entre mujeres y hombres y sobre prevención de la violencia de género, que se dirigirán:","o":["al personal de nuevo ingreso.","a todo su personal.","al personal directivo y a los miembros de los órganos de selección.","al personal que lo solicite voluntariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a todo su personal</mark></span>El <span class=\"ref-norma\">art. 61.2 de la LO 3/2007</span> se dispone: <span class=\"ref-concepto\">\"que se dirigirán a todo su personal\"</span>. Los cursos se dirigen a todo su personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · 2.5 Compromisos · 2.5.1 Compromisos de la Administración General del Estado EXOF EX","q":[{"i":"16-190","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. El inicio de las actuaciones del protocolo no afecta al derecho de las personas implicadas a solicitar las actuaciones administrativas o de cualquier tipo que se estimen adecuadas. Tampoco a su derecho a:","o":["La tutela judicial efectiva.","La asistencia jurídica gratuita.","La presunción de inocencia.","La indemnidad frente a represalias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La tutela judicial efectiva</mark></span>El <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Tampoco a su derecho a la tutela judicial efectiva\"</span>"},{"i":"16-ia-1231","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá declarar formalmente por escrito y difundir el rechazo a cualquier actuación que pueda ser constitutiva de acoso sexual y acoso por razón de sexo, en todas sus formas y modalidades, sin atender a quién sea la víctima o la persona acosadora, ni cual sea su situación en la organización, garantizando el derecho de las empleadas y empleados públicos a recibir:","o":["un trato imparcial y confidencial.","una respuesta en el plazo de diez días.","un trato respetuoso y digno.","una protección integral y gratuita."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un trato respetuoso y digno</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"garantizando el derecho de las empleadas y empleados públicos a recibir un trato respetuoso y digno\"</span>. Se garantiza el derecho a recibir un trato respetuoso y digno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1232","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá difundir la declaración de rechazo del acoso a todas las personas que prestan servicio dentro de su ámbito de dirección y/o organización, incluidas las personas en formación, las que realizan prácticas no laborales, el personal de las empresas __________, etc.","o":["contratistas","externas","subcontratadas","colaboradoras"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">externas</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"las que realizan prácticas no laborales, el personal de las empresas externas, etc\"</span>. Se incluye al personal de las empresas externas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1233","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá promover una cultura de prevención contra el acoso sexual o acoso por razón de sexo, a través de acciones formativas e informativas de sensibilización para todo su personal, impidiendo los comportamientos, actitudes o acciones que son o puedan ser:","o":["ofensivas, humillantes, degradantes, molestas, intimidatorias u hostiles.","ofensivas, humillantes, degradantes, intimidatorias o discriminatorias.","ofensivas, vejatorias, degradantes, molestas, intimidatorias u hostiles, previo informe de la unidad policial competente.","ofensivas, humillantes, degradantes, molestas o intimidatorias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ofensivas, humillantes, degradantes, molestas, intimidatorias u hostiles</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que son o puedan ser ofensivas, humillantes, degradantes, molestas, intimidatorias u hostiles\"</span>. La enumeración es ofensivas, humillantes, degradantes, molestas, intimidatorias u hostiles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1234","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá comprometerse a comunicar, tramitar e investigar cualquier conducta que pueda ser constitutiva de acoso sexual y/o acoso por razón de sexo, aplicando los principios de profesionalidad, objetividad, imparcialidad, celeridad, respeto a la persona y tratamiento reservado de la información, con el consiguiente deber de __________ para todas las personas implicadas en el desarrollo del protocolo.","o":["secreto","reserva","discreción","sigilo"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sigilo</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"con el consiguiente deber de sigilo para todas las personas implicadas en el desarrollo del protocolo\"</span>. El deber que se impone es el de sigilo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1235","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá identificar y difundir la unidad responsable de recibir y tramitar las solicitudes de activación del protocolo, así como:","o":["el listado de personas que integran el comité de asesoramiento, sin perjuicio de lo previsto en la normativa vigente.","el modelo de solicitud de activación del protocolo.","el listado de personas que pueden desempeñar la Asesoría Confidencial.","el procedimiento para presentar alegaciones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el listado de personas que pueden desempeñar la Asesoría Confidencial</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"así como el listado de personas que pueden desempeñar la Asesoría Confidencial\"</span>. Hay que difundir la unidad responsable y el listado de personas que pueden desempeñar la Asesoría Confidencial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1236","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Cada departamento ministerial y organismo o entidad pública deberá apoyar y asesorar a las presuntas víctimas de acoso sexual y acoso por razón de sexo, facilitando a las víctimas el acceso a servicios de apoyo psicosocial y/o acompañamiento integral de la administración __________ o local competente para su recuperación.","o":["estatal","autonómica","sanitaria","provincial, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">autonómica</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"acompañamiento integral de la administración autonómica o local competente para su recuperación\"</span>. Los servicios son los de la administración autonómica o local competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1238","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. El inicio de las actuaciones del protocolo no afecta al derecho de las personas implicadas a solicitar las actuaciones administrativas o de cualquier tipo que se estimen adecuadas. Tampoco a su derecho a:","o":["la asistencia jurídica gratuita.","la presunción de inocencia.","la indemnidad frente a represalias.","la tutela judicial efectiva."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la tutela judicial efectiva</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Tampoco a su derecho a la tutela judicial efectiva\"</span>. El inicio de las actuaciones no afecta al derecho a la tutela judicial efectiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1239","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.5 Compromisos. Para hacer efectivo el compromiso de actuación, cada departamento ministerial u organismo público se dotará de los procedimientos, acciones e instrumentos que permitan prevenir, detectar, abordar y __________ las conductas constitutivas de acoso sexual y acoso por razón de sexo.","o":["sancionar, salvo que la autoridad judicial disponga otra cosa.","evitar","erradicar","reparar"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">erradicar</mark></span>En el <span class=\"ref-norma\">apdo. 2.5.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que permitan prevenir, detectar, abordar y erradicar las conductas constitutivas de acoso sexual y acoso por razón de sexo\"</span>. Los instrumentos permiten prevenir, detectar, abordar y erradicar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual","q":[{"i":"16-193","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo II. Comité de Asesoramiento. El comité de asesoramiento será paritario y estará formado por dos personas del departamento ministerial u organismo dependiente y que, al menos una de ellas, tengan la condición de:","o":["Miembros de la comisión de igualdad.","Representantes del personal.","Personal directivo.","Asesores confidenciales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Asesores confidenciales</mark></span>El <span class=\"ref-norma\">Anexo II de la RD 247/2024 (Protocolo)</span> dispone: <span class=\"ref-concepto\">\"Dos personas del departamento ministerial u organismo dependiente y que, al menos una de ellas, tengan la condición de asesores confidenciales\"</span>"},{"i":"16-ia-1133","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Real Decreto 247/2024: entrada en vigor. El presente real decreto, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos, entrará en vigor:","o":["el día siguiente al de su publicación en el «Boletín Oficial del Estado».","a los veinte días de su publicación en el «Boletín Oficial del Estado», salvo que la autoridad judicial disponga otra cosa.","el mismo día de su publicación en el «Boletín Oficial del Estado».","a los seis meses de su publicación en el «Boletín Oficial del Estado»."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el día siguiente al de su publicación en el «Boletín Oficial del Estado»</mark></span>En el <span class=\"ref-norma\">apdo. Segundo de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"El presente real decreto entrará en vigor el día siguiente al de su publicación en el «Boletín Oficial del Estado»\"</span>. El real decreto entra en vigor el día siguiente al de su publicación; la aplicación del protocolo tiene su propio plazo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1201","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Objetivo general del protocolo: evitar las posibles situaciones de acoso sexual y acoso por razón de sexo en la Administración General del Estado y en los organismos vinculados o dependientes de la misma y __________ de manera efectiva en caso de que éstas lleguen a producirse.","o":["afrontarlas","sancionarlas","erradicarlas","combatirlas"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">afrontarlas</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"y afrontarlas de manera efectiva en caso de que éstas lleguen a producirse\"</span>. El objetivo general es evitar las situaciones de acoso y afrontarlas de manera efectiva si llegan a producirse. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1202","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Entre los objetivos específicos del protocolo se encuentra fomentar la cultura __________ del acoso sexual y/o por razón de sexo en todos los ámbitos y estamentos de la Administración General del Estado.","o":["formativa","informativa","sancionadora","preventiva"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">preventiva</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Fomentar la cultura preventiva del acoso sexual y/o por razón de sexo en todos los ámbitos y estamentos\"</span>. Se trata de fomentar la cultura preventiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1203","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Entre los objetivos específicos del protocolo se encuentra manifestar la tolerancia __________ de la Administración General del Estado frente a las situaciones de acoso sexual y por razón de sexo que puedan detectarse en cualesquiera estamentos de la organización.","o":["mínima","limitada","cero","absoluta"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cero</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Manifestar la tolerancia cero de la Administración General del Estado frente a las situaciones de acoso sexual y por razón de sexo\"</span>. El texto habla de tolerancia cero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1205","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Entre los objetivos específicos del protocolo se encuentra esclarecer internamente, de manera __________ las comunicaciones de acoso en aras a precisar si se ha producido una situación de acoso sexual y/o por razón de sexo.","o":["ágil, rápida y confidencial","ágil, rápida y objetiva","rápida, imparcial y confidencial","ágil, eficaz y confidencial"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ágil, rápida y confidencial</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Esclarecer internamente, de manera ágil, rápida y confidencial las comunicaciones de acoso\"</span>. El esclarecimiento interno ha de ser ágil, rápido y confidencial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1206","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Entre los objetivos específicos del protocolo se encuentra garantizar la seguridad, integridad y dignidad de las personas implicadas, la aplicación de las medidas que en cada caso procedan para la protección de las víctimas en todo momento, apoyando a la persona que ha sufrido el acoso para evitar su:","o":["estigmatización social, salvo que la autoridad judicial disponga otra cosa.","victimización primaria.","desprotección laboral.","victimización secundaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">victimización secundaria</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"apoyando a la persona que ha sufrido el acoso para evitar su victimización secundaria\"</span>. Se apoya a la persona que ha sufrido el acoso para evitar su victimización secundaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1207","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. El protocolo resulta de aplicación también a las personas que, no teniendo una relación laboral, prestan servicios o colaboran con la Administración General del Estado o algunos de sus organismos, tales como:","o":["personas en formación, las que realizan prácticas laborales o aquellas que realizan cualquier tipo de colaboración análoga, previo informe de la unidad policial competente.","personas en formación y personal de empresas externas contratadas, pero no las que realizan prácticas no laborales.","personas en formación, las que realizan prácticas no laborales o aquellas que realizan cualquier tipo de colaboración análoga.","personas en formación, las becarias y quienes realizan cualquier tipo de voluntariado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">personas en formación, las que realizan prácticas no laborales o aquellas que realizan cualquier tipo de colaboración análoga</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"tales como personas en formación, las que realizan prácticas no laborales o aquellas que realizan cualquier tipo de colaboración análoga\"</span>. El protocolo alcanza a personas en formación, prácticas no laborales y cualquier colaboración análoga. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1208","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Cuando el personal perteneciente a empresas externas que desarrollen su trabajo en centros de la Administración General del Estado se considere víctima de acoso sexual o por razón de sexo por parte de personal bajo el ámbito de dirección y organización de la Administración y active el protocolo, la Administración comunicará la activación del protocolo:","o":["a la empresa de la presunta persona acosadora.","a la empresa de la víctima.","a la Inspección de Trabajo y Seguridad Social.","a la representación sindical de la empresa externa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la empresa de la víctima</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"La Administración comunicará a la empresa de la víctima la activación del protocolo\"</span>. La activación se comunica a la empresa de la víctima para que adopte las medidas y procedimientos que correspondan en su ámbito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1209","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. Cuando el personal bajo el ámbito de dirección y organización de la Administración General del Estado se considere víctima de acoso por parte de personal de empresas externas y active el protocolo, la Administración comunicará a la empresa de la presunta persona acosadora la activación del protocolo para que adopte las medidas y procedimientos que correspondan, que en todo caso garantizarán:","o":["la separación física de las personas afectadas.","la suspensión de empleo de la persona acosadora.","la separación física de la víctima y su traslado a otro centro.","el cese de la relación contractual con la empresa externa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la separación física de las personas afectadas</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que en todo caso garantizarán la separación física de las personas afectadas\"</span>. Las medidas garantizarán en todo caso la separación física de las personas afectadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1211","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.2 Objetivos. A efecto del protocolo, estará incluida toda forma en que pueda producirse el acoso sexual o por razón de sexo, incluyendo el realizado a través de medios __________, informáticos o ciberacoso.","o":["telemáticos","digitales","tecnológicos","electrónicos, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tecnológicos</mark></span>En el <span class=\"ref-norma\">apdo. 2.2.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"incluyendo el realizado a través de medios tecnológicos, informáticos o ciberacoso\"</span>. Se incluyen los medios tecnológicos, informáticos o ciberacoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1243","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. La prevención de unas conductas inaceptables, como son las conductas de acoso sexual o por razón de sexo, debe plantearse en el contexto de una acción general y __________ de prevención, con objeto de identificar los factores que puedan contribuir a crear un entorno laboral exento de acoso.","o":["coordinada","preventiva","proactiva","continuada"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">proactiva</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"debe plantearse en el contexto de una acción general y proactiva de prevención\"</span>. La acción es general y proactiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1244","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. Todos los departamentos ministeriales y organismos públicos deberán impulsar actuaciones preventivas frente al acoso, con objeto de prevenir y evitar los comportamientos constitutivos de acoso sexual o acoso por razón de sexo en el trabajo y, en su caso, garantizar que se apliquen los procedimientos:","o":["disciplinarios oportunos.","sancionadores oportunos.","sancionadores y penales oportunos.","de actuación previstos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sancionadores oportunos</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"garantizar que se apliquen los procedimientos sancionadores oportunos\"</span>. Se garantiza que se apliquen los procedimientos sancionadores oportunos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1246","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. Entre las medidas de prevención figura la formación específica para el personal __________ o con equipos a su cargo, para capacitarles en identificar o detectar posibles situaciones de acoso sexual y por razón de sexo en sus unidades, así como en manejar o abordar adecuadamente este tipo de situaciones.","o":["técnico","de nuevo ingreso","sindical","directivo"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">directivo</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Formación específica para el personal directivo o con equipos a su cargo\"</span>. Se dirige al personal directivo o con equipos a su cargo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1249","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · III. Medidas de prevención frente al acoso sexual y acoso por razón de sexo. Entre las medidas de prevención figura la evaluación y revisión __________ del funcionamiento e implantación del protocolo.","o":["periódica","anual","semestral, salvo que la autoridad judicial disponga otra cosa.","bienal"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">periódica</mark></span>En el <span class=\"ref-norma\">apdo. III de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Evaluación y revisión periódica del funcionamiento e implantación del protocolo\"</span>. La evaluación y revisión es periódica, sin plazo fijo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1301","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.1 Consideraciones generales. La persona titular de la jefatura superior de personal del departamento ministerial u organismo público deberá identificar, específicamente, la unidad responsable de la recepción de:","o":["la comunicación de activación del protocolo.","las alegaciones de la víctima al informe de conclusiones.","los informes de valoración de la asesoría confidencial.","las solicitudes de constitución del comité de asesoramiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la comunicación de activación del protocolo</mark></span>En el <span class=\"ref-norma\">apdo. 4.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"deberá identificar, específicamente, la unidad responsable de la recepción de la comunicación de activación del protocolo\"</span>. La jefatura superior de personal identifica la unidad responsable de la recepción de la comunicación de activación del protocolo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1302","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.1 Consideraciones generales. Siempre que existan indicios suficientes de la existencia de acoso sexual o acoso por razón de sexo, la unidad receptora propondrá, en cualquier momento, al órgano competente del departamento ministerial o del organismo público la adopción de aquellas medidas que eviten que la situación de acoso perdure y genere un mayor __________ a la víctima.","o":["perjuicio","sufrimiento","riesgo","daño"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">daño</mark></span>En el <span class=\"ref-norma\">apdo. 4.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que eviten que la situación de acoso perdure y genere un mayor daño a la víctima\"</span>. Las medidas evitan que la situación perdure y genere un mayor daño a la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1303","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.1 Consideraciones generales. Cuando existan evidencias suficientes de acoso sexual o acoso por razón de sexo, la unidad receptora, o la asesoría confidencial, deberá poner en conocimiento del titular de la jefatura superior de personal del departamento ministerial u organismo público los hechos sucedidos, previo conocimiento de:","o":["la presunta persona acosadora.","la representación sindical.","la víctima.","el órgano competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la víctima</mark></span>En el <span class=\"ref-norma\">apdo. 4.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"los hechos sucedidos, previo conocimiento de la víctima\"</span>. Con evidencias suficientes se ponen los hechos en conocimiento de la jefatura superior de personal, previo conocimiento de la víctima; con meros indicios suficientes solo se proponen medidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1304","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.1 Consideraciones generales. La unidad receptora deberá disponer de un listado actualizado de personas que hayan recibido la formación específica en asesoría confidencial, que dará a conocer y estará a disposición de todo el personal del departamento ministerial u organismo público, así como determinará:","o":["el número máximo de asesores por centro de trabajo, en los términos que se determinen reglamentariamente.","la forma en que se podrá contactar con estas personas.","los criterios de designación de los asesores.","el plazo en que deberán atender las comunicaciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la forma en que se podrá contactar con estas personas</mark></span>En el <span class=\"ref-norma\">apdo. 4.1 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"así como determinará la forma en que se podrá contactar con estas personas\"</span>. La unidad receptora determina la forma de contactar con las personas del listado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1305","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Con el fin de garantizar la confidencialidad en la aplicación del protocolo, se deberá establecer un buzón de correo electrónico, cuyo uso es exclusivo para la presentación de las comunicaciones y solicitudes de activación del protocolo, y al que sólo tendrá acceso el personal designado por la unidad receptora. En todo caso, se dispondrá también de:","o":["un buzón físico.","un teléfono de atención específico.","una sede electrónica accesible.","un formulario web anónimo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un buzón físico</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"En todo caso, se dispondrá también de un buzón físico\"</span>. Además del buzón de correo electrónico, en todo caso habrá un buzón físico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1306","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Para que no figuren datos personales, la unidad receptora, al recibir la comunicación o solicitud de activación del protocolo, asignará un código numérico a cada una de las partes que se utilizará en todas las __________ del protocolo.","o":["actuaciones","comunicaciones","etapas","fases"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">fases</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"asignará un código numérico a cada una de las partes que se utilizará en todas las fases del protocolo\"</span>. El código numérico se utiliza en todas las fases del protocolo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1307","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Las actuaciones previstas en el protocolo se inician por la remisión de una comunicación:","o":["escrita a la asesoría confidencial.","escrita a la jefatura superior de personal.","verbal o escrita a la unidad receptora.","verbal a la asesoría confidencial, confirmada por escrito en veinticuatro horas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">verbal o escrita a la unidad receptora</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se inician por la remisión de una comunicación (verbal o escrita) a la unidad receptora\"</span>. La comunicación puede ser verbal o escrita y se remite a la unidad receptora. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1309","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Una vez recibida la comunicación, la unidad receptora la pondrá en conocimiento de la Asesoría Confidencial inmediatamente (__________), para que, en el marco de sus funciones, proceda a un análisis de los hechos descritos, acompañe, asesore e informe a la víctima sobre las distintas actuaciones posibles.","o":["24 horas","48 horas","72 horas","tres días hábiles"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">24 horas</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"la unidad receptora lo pondrá en conocimiento de la Asesoría Confidencial inmediatamente (24 horas)\"</span>. El plazo es inmediato, 24 horas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1310","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. La víctima podrá solicitar al asesor o asesora confidencial que considere, dentro de los existentes y siempre que:","o":["lo autorice la unidad receptora.","no haya intervenido en etapas anteriores.","pertenezca a su mismo departamento ministerial.","las circunstancias del momento lo permitan."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las circunstancias del momento lo permitan</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"La víctima podrá solicitar al asesor o asesora confidencial que considere, dentro de los existentes y siempre que las circunstancias del momento lo permitan\"</span>. La víctima elige asesor dentro de los existentes y siempre que las circunstancias del momento lo permitan. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1311","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Las medidas organizativas previas que la unidad receptora, por recomendación de la asesoría confidencial, proponga de forma debidamente motivada al órgano competente para garantizar la protección y la indemnidad frente a represalias de las personas implicadas no podrán ser:","o":["mantenidas más allá de la finalización de la fase de investigación, salvo que la autoridad judicial disponga otra cosa.","adoptadas sin audiencia de la presunta persona acosadora.","una solución permanente en las condiciones laborales de las partes.","aplicadas a la víctima en ningún caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una solución permanente en las condiciones laborales de las partes</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Las medidas no podrán ser una solución permanente en las condiciones laborales de las partes\"</span>. Las medidas no pueden ser una solución permanente en las condiciones laborales de las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1313","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.2 Inicio de las actuaciones. Los departamentos ministeriales y los organismos públicos, así como, si fuera el caso, las empresas externas u otros terceros afectados, tendrán la obligación de colaborar a lo largo de todo el proceso con:","o":["la asesoría confidencial.","la unidad receptora.","el comité de asesoramiento.","la jefatura superior de personal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la asesoría confidencial</mark></span>En el <span class=\"ref-norma\">apdo. 4.2 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"tendrán la obligación de colaborar con la asesoría confidencial a lo largo de todo el proceso\"</span>. La obligación de colaborar lo es con la asesoría confidencial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1326","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · IV. Procedimiento de desarrollo de las actuaciones · 4.5 Información. Con carácter general, de las actuaciones y las conclusiones adoptadas se informará a las partes implicadas. Asimismo, se emitirá la información estadística a la correspondiente comisión de igualdad dependiente de:","o":["la Mesa General de Negociación de la Administración General del Estado.","la Dirección General de la Función Pública.","la Comisión Técnica de Igualdad.","la Mesa Delegada, preservando la intimidad de las personas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Mesa Delegada, preservando la intimidad de las personas</mark></span>En el <span class=\"ref-norma\">apdo. 4.5 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se emitirá la información estadística a la correspondiente comisión de igualdad dependiente de la Mesa Delegada, preservando la intimidad de las personas\"</span>. La comisión de igualdad correspondiente depende de la Mesa Delegada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1328","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · V. Evaluación y seguimiento del informe de conclusiones. Anualmente, cada departamento ministerial y organismo público remitirá:","o":["a la Mesa General de Negociación, una memoria de las actividades realizadas a lo largo del año, salvo que la autoridad judicial disponga otra cosa.","a la Dirección General de la Función Pública, una memoria de las actividades realizadas a lo largo del año.","a la Comisión Técnica de Igualdad, un informe de los casos tramitados a lo largo del año.","al Instituto de las Mujeres, una memoria de las actividades realizadas a lo largo del año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la Dirección General de la Función Pública, una memoria de las actividades realizadas a lo largo del año</mark></span>En el <span class=\"ref-norma\">apdo. V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Anualmente, cada departamento ministerial y organismo público, remitirá a la Dirección General de la Función Pública, una memoria de las actividades realizadas a lo largo del año\"</span>. La memoria anual se remite a la Dirección General de la Función Pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1329","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · V. Evaluación y seguimiento del informe de conclusiones. La relación que cada departamento ministerial y organismo público remite a la Dirección General de la Función Pública estará debidamente __________ y no se deberán facilitar datos personales.","o":["anonimizada","disociada","agregada","codificada, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anonimizada</mark></span>En el <span class=\"ref-norma\">apdo. V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Esta relación, debidamente anonimizada, comprenderá los informes de conclusiones\"</span>. La relación es debidamente anonimizada y no se facilitan datos personales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1330","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · V. Evaluación y seguimiento del informe de conclusiones. La relación anual comprenderá los informes de conclusiones que hayan determinado la solicitud de apertura de un procedimiento disciplinario por la posible existencia de acoso sexual o acoso por razón de sexo; los que hayan acordado la solicitud de un procedimiento disciplinario por la posible existencia de alguna otra falta disciplinaria y:","o":["aquellos que hayan sido archivados por desistimiento de la víctima.","aquellos que hayan sido objeto de alegaciones de la víctima.","aquellos en los que se hayan adoptado medidas organizativas cautelares, sin perjuicio de lo previsto en la normativa vigente.","aquellos que hayan determinado que no existe ninguna conducta infractora."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">aquellos que hayan determinado que no existe ninguna conducta infractora</mark></span>En el <span class=\"ref-norma\">apdo. V de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"los que hayan acordado la solicitud de un procedimiento disciplinario por la posible existencia de alguna otra falta disciplinaria y aquellos que hayan determinado que no existe ninguna conducta infractora\"</span>. Se incluyen también los informes que determinaron que no existe ninguna conducta infractora. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1334","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · VI. Implantación del protocolo. Se deberá tener en cuenta especialmente la estructura, ubicación y dispersión geográfica del departamento ministerial u organismo público, procurando que las actuaciones previstas en el protocolo se desarrollen, preferiblemente, en ámbito __________ donde se formule la comunicación.","o":["autonómico","local","territorial","provincial"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">provincial</mark></span>En el <span class=\"ref-norma\">apdo. VI de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se desarrollen, preferiblemente, en ámbito provincial donde se formule la comunicación\"</span>. Las actuaciones se desarrollan, preferiblemente, en el ámbito provincial donde se formule la comunicación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1343","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · Anexo II. Comité de Asesoramiento. Los dos representantes del personal que forman parte del comité de asesoramiento serán elegidos por:","o":["la jefatura superior de personal del departamento ministerial u organismo público, sin perjuicio de lo previsto en la normativa vigente.","la comisión de igualdad departamental.","los representantes de las organizaciones sindicales presentes en la Mesa Delegada.","la víctima, de entre los representantes unitarios del departamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los representantes de las organizaciones sindicales presentes en la Mesa Delegada</mark></span>En el <span class=\"ref-norma\">Anexo II de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que será elegido por los representantes de las organizaciones sindicales presentes en la Mesa Delegada\"</span>. Los elige la representación de las organizaciones sindicales presentes en la Mesa Delegada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Protocolo · 2.4 Definiciones ✱","q":[{"i":"16-ia-1223","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Se entiende por hostigamiento toda conducta intimidatoria, degradante, humillante y ofensiva que se origina __________ y que es percibida como tal por quien la sufre.","o":["internamente","reiteradamente","externamente","jerárquicamente"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">externamente</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"que se origina externamente y que es percibida como tal por quien la sufre\"</span>. El hostigamiento se origina externamente y es percibido como tal por quien lo sufre. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1224","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Entre los elementos del acoso por razón de sexo figura el atentado __________ a la dignidad de la víctima y percibida subjetivamente por esta como tal.","o":["directo","objetivo","grave","reiterado"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">objetivo</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Atentado objetivo a la dignidad de la víctima y percibida subjetivamente por esta como tal\"</span>. El atentado es objetivo a la dignidad y percibido subjetivamente por la víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1225","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. El ataque a la dignidad de quien sufre acoso por razón de sexo no impide la concurrencia de daño a otros derechos fundamentales de la víctima, tales como el derecho a no sufrir discriminación, ni daños a la salud, psíquica o física. Esto se denomina:","o":["resultado pluriofensivo.","resultado pluridimensional.","resultado agravado.","resultado concurrente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">resultado pluriofensivo</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"Resultado pluriofensivo. El ataque a la dignidad de quien sufre acoso por razón de sexo no impide la concurrencia de daño a otros derechos fundamentales de la víctima\"</span>. El elemento se llama resultado pluriofensivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1226","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Todo trato desfavorable relacionado con el embarazo, la maternidad, paternidad o asunción de otros __________ estará amparado por la aplicación de este protocolo cuando se den los requisitos definidos.","o":["deberes familiares, salvo que la autoridad judicial disponga otra cosa.","cargos públicos","permisos","cuidados familiares"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuidados familiares</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"relacionado con el embarazo, la maternidad, paternidad o asunción de otros cuidados familiares estará amparado por la aplicación de este protocolo\"</span>. Se refiere al embarazo, maternidad, paternidad o asunción de otros cuidados familiares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1227","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. El que solicitare favores de naturaleza sexual, para sí o para un tercero, en el ámbito de una relación laboral, docente, de prestación de servicios o análoga, continuada o habitual, y con tal comportamiento provocare a la víctima una situación objetiva y gravemente intimidatoria, hostil o humillante, será castigado, como autor de acoso sexual, con la pena de:","o":["prisión de tres a seis meses o multa de seis a diez meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de seis a doce meses.","prisión de seis meses a un año o multa de doce a veinticuatro meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de dieciocho a veinticuatro meses.","prisión de seis a doce meses o multa de diez a quince meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de doce a quince meses.","prisión de uno a dos años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de dieciocho a veinticuatro meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">prisión de seis a doce meses o multa de diez a quince meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de doce a quince meses</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"con la pena de prisión de seis a doce meses o multa de diez a quince meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de doce a quince meses\"</span>. El tipo básico es prisión de seis a doce meses o multa de diez a quince meses e inhabilitación especial de doce a quince meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1228","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Si el culpable de acoso sexual hubiera cometido el hecho prevaliéndose de una situación de superioridad laboral, docente o jerárquica, o sobre persona sujeta a su guarda o custodia, o con el anuncio expreso o tácito de causar a la víctima un mal relacionado con las legítimas expectativas que aquella pueda tener en el ámbito de la indicada relación, la pena será de prisión de __________ e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de dieciocho a veinticuatro meses.","o":["seis a doce meses","uno a dos años","dos a tres años","uno a tres años"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">uno a dos años</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"la pena será de prisión de uno a dos años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de dieciocho a veinticuatro meses\"</span>. El tipo agravado es prisión de uno a dos años e inhabilitación especial de dieciocho a veinticuatro meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1229","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Cuando la víctima de acoso sexual se halle en una situación de especial vulnerabilidad por razón de su edad, enfermedad o discapacidad, la pena se impondrá en su:","o":["mitad superior.","grado máximo.","mitad inferior.","mitad superior, con inhabilitación absoluta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mitad superior</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"la pena se impondrá en su mitad superior\"</span>. La pena se impone en su mitad superior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"16-ia-1230","p":"Real Decreto 247/2024, de 8 de marzo, por el que se aprueba el Protocolo de actuación frente al acoso sexual y al acoso por razón de sexo en el ámbito de la Administración General del Estado y de sus organismos públicos. Protocolo · II. Política de prevención · 2.4 Definiciones. Cuando una persona jurídica sea responsable del delito de acoso sexual, se le impondrá la pena de multa de:","o":["doce a veinticuatro meses.","seis meses a un año.","uno a tres años.","seis meses a dos años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seis meses a dos años</mark></span>En el <span class=\"ref-norma\">apdo. 2.4 de la RD 247/2024 (Protocolo)</span> se dispone: <span class=\"ref-concepto\">\"se le impondrá la pena de multa de seis meses a dos años\"</span>. La persona jurídica responsable es castigada con multa de seis meses a dos años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
